// Culture numérique (banque 2) : recherche et veille, données et tableur, communication, création de contenus,
// matériel et réseaux, sécurité, RGPD et CNIL, santé et environnement, notions (IA, cloud, blockchain, API),
// administration numérique, DGFiP et numérique, réglementation française et européenne.
BANK.push(
// --- Recherche et veille d'information ---
{id:"nu2-001",t:"num",q:"Sur la plupart des moteurs de recherche, comment rechercher une expression exacte, mot pour mot ?",o:["En la plaçant entre parenthèses","En la plaçant entre guillemets","En séparant les mots par des virgules","En l'écrivant tout en majuscules"],a:1,e:"Les guillemets imposent la suite exacte des mots (ex. « prélèvement à la source »).",u:["https://fr.wikipedia.org/wiki/Moteur_de_recherche"],s:"Banque numérique"},
{id:"nu2-002",t:"num",q:"Sur la plupart des moteurs de recherche, comment exclure un mot des résultats ?",o:["En le plaçant entre crochets","En le faisant suivre d'un astérisque","En le faisant précéder du signe moins (-)","En l'écrivant en minuscules"],a:2,e:"Ex. : jaguar -voiture écarte les pages qui contiennent « voiture ».",s:"Banque numérique"},
{id:"nu2-003",t:"num",q:"Quel opérateur de recherche limite les résultats aux pages d'un site ou d'un domaine (par exemple les sites en .gouv.fr) ?",o:["filetype:","intitle:","related:","site:"],a:3,e:"Ex. : site:gouv.fr facturation électronique. L'opérateur filetype: filtre, lui, le format du fichier (pdf, xlsx…).",s:"Banque numérique"},
{id:"nu2-004",t:"num",q:"Lequel de ces moteurs de recherche est d'origine française ?",o:["Bing","Baidu","Qwant","Yandex"],a:2,e:"Qwant met en avant le respect de la vie privée ; Bing est américain, Baidu chinois, Yandex russe.",u:["https://fr.wikipedia.org/wiki/Qwant"],s:"Banque numérique"},
{id:"nu2-005",t:"num",q:"Qu'est-ce qu'un métamoteur de recherche ?",o:["Un outil qui interroge simultanément plusieurs moteurs et regroupe leurs résultats","Un moteur réservé à la recherche d'images","Un annuaire de sites classés à la main","Un moteur qui n'indexe que les métadonnées des fichiers"],a:0,e:"Il n'a pas son propre index : il agrège les réponses d'autres moteurs.",u:["https://fr.wikipedia.org/wiki/Métamoteur"],s:"Banque numérique"},
{id:"nu2-006",t:"num",q:"Pour évaluer la fiabilité d'une page web, quel critère est le plus pertinent ?",o:["L'identification de l'auteur et de sa qualité, la date et les sources citées","Sa position en tête des résultats du moteur de recherche","Le nombre de partages sur les réseaux sociaux","La présence de nombreuses illustrations"],a:0,e:"Le rang dans un moteur ou la popularité ne garantissent pas l'exactitude : on identifie la source et on recoupe.",s:"Banque numérique"},
{id:"nu2-007",t:"num",q:"Que désigne le terme « infox », recommandé en français pour traduire « fake news » ?",o:["Une information provenant d'une source officielle","Une information fausse ou trompeuse, souvent diffusée délibérément pour manipuler","Une lettre d'information électronique","Une publicité ciblée"],a:1,e:"Terme publié au Journal officiel en 2018. Pour s'en prémunir : vérifier l'origine, la date et recouper les sources.",u:["https://fr.wikipedia.org/wiki/Infox"],s:"Banque numérique"},
{id:"nu2-008",t:"num",q:"À quoi sert une recherche d'image inversée ?",o:["À retourner une image à l'horizontale","À compresser une image","À convertir une image en couleurs inversées","À retrouver l'origine et les autres publications d'une image"],a:3,e:"Elle permet de démasquer une photo ancienne ou détournée présentée comme récente.",s:"Banque numérique"},
{id:"nu2-009",t:"num",q:"Quel outil de veille envoie automatiquement par courriel les nouveaux contenus publiés en ligne correspondant à des mots-clés choisis ?",o:["Un marque-page (favori)","L'historique de navigation","Un service d'alerte (type Google Alertes)","Un bloqueur de publicités"],a:2,e:"Avec les flux RSS, les alertes sont les outils de base de la veille informationnelle.",s:"Banque numérique"},
{id:"nu2-010",t:"num",q:"Que désigne la « bulle de filtres » ?",o:["Un filtre antispam de messagerie","L'enfermement de l'internaute dans des contenus conformes à ses goûts, du fait de la personnalisation par les algorithmes","Un pare-feu intégré à la box","Une technique de compression vidéo"],a:1,e:"Notion popularisée par Eli Pariser (2011) : la personnalisation réduit la diversité des points de vue rencontrés.",u:["https://fr.wikipedia.org/wiki/Bulle_de_filtres"],s:"Banque numérique"},
{id:"nu2-011",t:"num",q:"Qu'est-ce que le référencement naturel (SEO) ?",o:["L'optimisation d'un site pour améliorer sa place dans les résultats non payants des moteurs","L'achat d'annonces sponsorisées","La déclaration d'un site auprès de la CNIL","L'inscription d'un site dans l'annuaire de l'État"],a:0,e:"Le référencement payant (SEA) correspond aux liens sponsorisés.",u:["https://fr.wikipedia.org/wiki/Optimisation_pour_les_moteurs_de_recherche"],s:"Banque numérique"},
{id:"nu2-012",t:"num",q:"Que permet réellement la navigation privée d'un navigateur ?",o:["Rendre l'internaute anonyme vis-à-vis de son fournisseur d'accès et des sites visités","Chiffrer toutes les communications","Ne pas conserver sur l'appareil l'historique, les cookies et les données saisies pendant la session","Bloquer tous les logiciels malveillants"],a:2,e:"Le fournisseur d'accès, l'employeur ou les sites visités peuvent toujours voir l'activité.",u:["https://fr.wikipedia.org/wiki/Navigation_privée"],s:"Banque numérique"},

// --- Gestion et traitement des données ---
{id:"nu2-013",t:"num",q:"Que renseigne l'extension d'un nom de fichier (par exemple .docx ou .pdf) ?",o:["La taille du fichier","La date de création du fichier","Le nom de l'auteur","Le format du fichier, ce qui permet au système de choisir le logiciel pour l'ouvrir"],a:3,e:"Renommer l'extension ne convertit pas le fichier : il faut l'enregistrer dans un autre format.",u:["https://fr.wikipedia.org/wiki/Extension_de_nom_de_fichier"],s:"Banque numérique"},
{id:"nu2-014",t:"num",q:"Quelle extension correspond à un document texte au format OpenDocument, celui de LibreOffice Writer ?",o:[".ods",".odp",".docx",".odt"],a:3,e:".ods : feuille de calcul ; .odp : présentation ; .docx : format de Microsoft Word.",u:["https://fr.wikipedia.org/wiki/OpenDocument"],s:"Banque numérique"},
{id:"nu2-015",t:"num",q:"Lequel de ces formats d'image repose sur une compression avec perte ?",o:["PNG","JPEG","BMP","SVG"],a:1,e:"Le JPEG supprime des détails peu visibles pour alléger le fichier ; le PNG compresse sans perte ; le SVG est vectoriel.",u:["https://fr.wikipedia.org/wiki/JPEG"],s:"Banque numérique"},
{id:"nu2-016",t:"num",q:"Qu'est-ce qu'un fichier CSV ?",o:["Un fichier texte de données en tableau, dont les valeurs sont séparées par un délimiteur (virgule ou point-virgule)","Un fichier image compressé","Un fichier exécutable","Un fichier audio"],a:0,e:"Format simple, lisible par tous les tableurs, très utilisé pour publier des données ouvertes.",u:["https://fr.wikipedia.org/wiki/Comma-separated_values"],s:"Banque numérique"},
{id:"nu2-017",t:"num",q:"Selon la loi pour la confiance dans l'économie numérique (2004), qu'est-ce qu'un standard ouvert, par exemple un format de fichier ouvert ?",o:["Un format gratuit mais dont les spécifications restent secrètes","Un protocole ou format interopérable dont les spécifications techniques sont publiques et sans restriction d'accès ni de mise en œuvre","Un format lisible uniquement en ligne","Un format réservé aux administrations"],a:1,e:"Exemples : OpenDocument (ODF), PDF, PNG, CSV.",u:["https://fr.wikipedia.org/wiki/Format_ouvert"],s:"LCEN, art. 4"},
{id:"nu2-018",t:"num",q:"Dans un tableur, quelle référence reste entièrement fixe lorsqu'on recopie une formule ?",o:["A1","(A1)","$A$1","#A1"],a:2,e:"Le symbole $ bloque la colonne et/ou la ligne : $A$1 est une référence absolue, A1 une référence relative, A$1 ou $A1 des références mixtes.",u:["https://fr.wikipedia.org/wiki/Tableur"],s:"Banque numérique"},
{id:"nu2-019",t:"num",q:"La cellule C3 contient =B$2*C2. On recopie cette formule vers le bas, en C4. Que contient C4 ?",o:["=B$3*C3","=B$2*C3","=B$2*C2","=C$2*D3"],a:1,e:"La ligne de B$2 est bloquée par le $ ; la référence relative C2 descend d'une ligne et devient C3.",s:"Banque numérique"},
{id:"nu2-020",t:"num",q:"La cellule C1 contient =A1+B1. On la recopie en C2. Quelle formule obtient-on ?",o:["=A1+B1","=B1+C1","=A2+B2","=A1+B2"],a:2,e:"Les références relatives se décalent du même nombre de lignes que la formule : une ligne plus bas.",s:"Banque numérique"},
{id:"nu2-021",t:"num",q:"La cellule B5 contient =B2*$A$1. On la recopie vers la droite, en C5. Quelle formule obtient-on ?",o:["=C2*$A$1","=C2*$B$1","=B2*$A$1","=C3*$A$1"],a:0,e:"B2 devient C2 (une colonne à droite) ; $A$1, référence absolue, ne bouge pas.",s:"Banque numérique"},
{id:"nu2-022",t:"num",q:"Quelle formule calcule la somme des cellules A1 à A10 ?",o:["=SOMME(A1;A10)","=TOTAL(A1-A10)","=AJOUTER(A1:A10)","=SOMME(A1:A10)"],a:3,e:"Les deux-points désignent une plage ; =SOMME(A1;A10) n'additionnerait que les deux cellules A1 et A10.",s:"Banque numérique"},
{id:"nu2-023",t:"num",q:"Les cellules B2 à B5 contiennent 10, 12, 14 et 16. Que renvoie =MOYENNE(B2:B5) ?",o:["12","13","14","52"],a:1,e:"(10 + 12 + 14 + 16) ÷ 4 = 52 ÷ 4 = 13.",s:"Banque numérique"},
{id:"nu2-024",t:"num",q:"Quelle fonction d'un tableur compte les cellules d'une plage qui remplissent une condition ?",o:["SOMME.SI","RECHERCHEV","MOYENNE","NB.SI"],a:3,e:"SOMME.SI additionne les valeurs qui répondent à une condition ; NB.SI les compte (COUNTIF en anglais).",s:"Banque numérique"},
{id:"nu2-025",t:"num",q:"En B1, une formule SI affiche « Admis » si A1 est supérieur ou égal à 10, et « Ajourné » sinon. A1 contient 10. Qu'affiche B1 ?",o:["Admis","Ajourné","#VALEUR!","Rien, la cellule reste vide"],a:0,e:"La condition A1>=10 est vraie pour 10 : la formule renvoie la valeur prévue si la condition est vraie.",s:"Banque numérique"},
{id:"nu2-026",t:"num",q:"À quoi sert la fonction RECHERCHEV d'un tableur ?",o:["À vérifier l'orthographe d'une colonne","À trier un tableau par ordre alphabétique","À rechercher un fichier sur le disque","À rechercher une valeur dans la première colonne d'un tableau et renvoyer la valeur d'une autre colonne sur la même ligne"],a:3,e:"Équivalent anglais : VLOOKUP.",s:"Banque numérique"},
{id:"nu2-027",t:"num",q:"Qu'est-ce qu'un tableau croisé dynamique ?",o:["Un tableau dont les cellules changent de couleur","Un tableau partagé en ligne entre plusieurs utilisateurs","Un outil qui synthétise une base de données (sommes, moyennes, comptages) selon des critères placés en lignes et en colonnes","Un graphique animé"],a:2,e:"Il permet, par exemple, de totaliser des montants par service et par mois sans écrire de formule.",u:["https://fr.wikipedia.org/wiki/Tableau_croisé_dynamique"],s:"Banque numérique"},
{id:"nu2-028",t:"num",q:"Que signifie l'erreur #DIV/0! dans une cellule ?",o:["La formule divise par zéro ou par une cellule vide","La colonne est trop étroite","La fonction est mal orthographiée","La cellule est protégée"],a:0,e:"Une colonne trop étroite affiche des #### ; un nom de fonction inconnu donne #NOM?.",s:"Banque numérique"},
{id:"nu2-029",t:"num",q:"Combien de cellules compte la plage B2:D5 ?",o:["8","9","12","15"],a:2,e:"3 colonnes (B, C, D) × 4 lignes (2 à 5) = 12 cellules.",s:"Banque numérique"},
{id:"nu2-030",t:"num",q:"Que sont les métadonnées d'un fichier ?",o:["Les données qui décrivent le fichier : auteur, date de création, coordonnées GPS d'une photo…","Les fichiers temporaires","Les données supprimées","Les copies de sauvegarde"],a:0,e:"Les données EXIF d'une photo peuvent révéler le lieu de prise de vue : on peut les effacer avant de la publier.",u:["https://fr.wikipedia.org/wiki/Métadonnée","https://fr.wikipedia.org/wiki/Exchangeable_image_file_format"],s:"Banque numérique"},

// --- Communication et collaboration ---
{id:"nu2-031",t:"num",q:"Dans un courriel, que signifie le champ « Cc » ?",o:["Courrier confidentiel","Copie cachée","Contrôle de conformité","Copie carbone : le destinataire reçoit une copie et son adresse est visible de tous"],a:3,e:"Pour masquer les adresses lors d'un envoi groupé, on utilise le champ Cci (copie carbone invisible).",u:["https://fr.wikipedia.org/wiki/Courrier_électronique"],s:"Banque numérique"},
{id:"nu2-032",t:"num",q:"Que fait la fonction « Répondre à tous » d'une messagerie ?",o:["Elle répond à l'expéditeur et aux destinataires visibles du message (champs « À » et « Cc »)","Elle répond à tous les contacts du carnet d'adresses","Elle répond uniquement aux destinataires en copie cachée","Elle transfère le message à toute l'organisation"],a:0,e:"Les adresses placées en Cci n'apparaissent pas dans le message reçu : elles ne sont pas reprises. À utiliser avec discernement.",s:"Banque numérique"},
{id:"nu2-033",t:"num",q:"Quelle plateforme est dédiée au signalement des courriels indésirables (pourriels) ?",o:["Signal Spam","PHAROS","FranceConnect","Pix"],a:0,e:"Les SMS indésirables se signalent au 33700 ; les contenus illicites sur PHAROS.",u:["https://fr.wikipedia.org/wiki/Signal_Spam","https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/spam-electronique"],s:"Banque numérique"},
{id:"nu2-034",t:"num",q:"Quelle plateforme du ministère de l'Intérieur permet de signaler un contenu illicite sur Internet (apologie du terrorisme, pédocriminalité, haine, escroquerie…) ?",o:["Signal Spam","Tchap","PHAROS","Chorus Pro"],a:2,e:"Plateforme d'harmonisation, d'analyse, de recoupement et d'orientation des signalements, accessible sur internet-signalement.gouv.fr.",u:["https://fr.wikipedia.org/wiki/PHAROS","https://internet-signalement.gouv.fr/"],s:"Banque numérique"},
{id:"nu2-035",t:"num",q:"Qu'est-ce que Tchap ?",o:["La messagerie instantanée sécurisée des agents publics","Le réseau social des usagers des services publics","L'assistant conversationnel de impots.gouv.fr","Un service de visioconférence grand public"],a:0,e:"Lancée par l'État en 2019 et fondée sur le protocole libre Matrix, elle évite le recours aux messageries grand public.",u:["https://fr.wikipedia.org/wiki/Tchap"],s:"Banque numérique"},
{id:"nu2-036",t:"num",q:"Que recouvre l'identité numérique d'une personne ?",o:["Uniquement son numéro de carte d'identité","Uniquement son adresse IP","Son seul mot de passe de messagerie","L'ensemble des informations et traces la concernant en ligne : profils, publications, commentaires, photos…"],a:3,e:"Elle se construit par ce que l'on publie, mais aussi par ce que d'autres publient sur soi.",u:["https://fr.wikipedia.org/wiki/Identité_numérique"],s:"Banque numérique"},
{id:"nu2-037",t:"num",q:"Que désigne l'e-réputation ?",o:["L'image d'une personne ou d'une organisation telle qu'elle ressort des contenus publiés en ligne","Le classement d'un site selon sa vitesse","Une note attribuée par la CNIL","Un certificat de sécurité"],a:0,e:"Elle se surveille, par exemple en recherchant régulièrement son nom dans un moteur.",u:["https://fr.wikipedia.org/wiki/E-réputation"],s:"Banque numérique"},
{id:"nu2-038",t:"num",q:"Que permet le droit au déréférencement ?",o:["Supprimer un site internet de l'annuaire de l'État","Demander à un moteur de recherche de retirer certains résultats associés à ses nom et prénom","Fermer le compte d'un tiers sur un réseau social","Effacer ses données de l'état civil"],a:1,e:"Consacré par la CJUE (arrêt Google Spain, 2014), puis rattaché au droit à l'effacement du RGPD. La page reste en ligne, mais n'apparaît plus dans les résultats.",u:["https://www.cnil.fr/fr/le-dereferencement-dun-contenu-dans-un-moteur-de-recherche"],s:"CNIL"},
{id:"nu2-039",t:"num",q:"En droit français, le harcèlement moral commis en ligne :",o:["N'est pas puni si son auteur est anonyme","Est un délit, et l'utilisation d'un service de communication en ligne constitue une circonstance aggravante","Ne relève que d'une amende civile","N'est puni que s'il vise un mineur"],a:1,e:"Code pénal, art. 222-33-2-2. La victime peut porter plainte et signaler les contenus.",u:["https://fr.wikipedia.org/wiki/Cyberharcèlement"],s:"Code pénal"},
{id:"nu2-040",t:"num",q:"Depuis la loi du 3 août 2018, le harcèlement « en meute » (raid numérique) est puni :",o:["Uniquement si chaque auteur a agi de façon répétée","Seulement s'il est commis sur un réseau social français","Seulement si la victime est un agent public","Même si chaque participant n'a agi qu'une fois, dès lors qu'il y a concertation ou conscience de participer à une répétition"],a:3,e:"La loi a visé les messages imposés à une même victime par plusieurs personnes, de manière concertée ou successive.",s:"Code pénal, art. 222-33-2-2"},
{id:"nu2-041",t:"num",q:"Quel numéro national, gratuit et anonyme, est dédié aux jeunes victimes de cyberharcèlement et de violences numériques ?",o:["3018","3919","3237","3939"],a:0,e:"Géré par l'association e-Enfance, il accompagne les victimes et leurs parents. Le 3919 concerne les violences faites aux femmes ; le 3939 est le numéro d'Allô Service public.",u:["https://e-enfance.org/le3018/"],s:"Banque numérique"},
{id:"nu2-042",t:"num",q:"Un agent public qui s'exprime sur les réseaux sociaux à titre personnel :",o:["N'est soumis à aucune obligation s'il utilise un pseudonyme","Doit obtenir une autorisation pour chaque publication","Peut diffuser librement les informations de son service","Reste tenu à l'obligation de réserve et à la discrétion professionnelle"],a:3,e:"Les obligations déontologiques s'appliquent aussi en ligne, même sous pseudonyme.",u:["https://fr.wikipedia.org/wiki/Devoir_de_réserve"],s:"Banque numérique"},
{id:"nu2-043",t:"num",q:"En France, à partir de quel âge un mineur peut-il consentir seul au traitement de ses données par un service en ligne ?",o:["13 ans","15 ans","16 ans","18 ans"],a:1,e:"Le RGPD fixe 16 ans par défaut et permet aux États de descendre jusqu'à 13 ans ; la France a retenu 15 ans. En dessous, le consentement est donné conjointement par le mineur et un titulaire de l'autorité parentale.",u:["https://www.cnil.fr/fr/recommandation-4-rechercher-le-consentement-dun-parent-pour-les-mineurs-de-moins-de-15-ans"],s:"Loi Informatique et libertés, art. 45"},

// --- Création de contenus ---
{id:"nu2-044",t:"num",q:"Dans un traitement de texte, quel est le principal intérêt des styles de titres (Titre 1, Titre 2…) ?",o:["Changer la langue du document","Protéger le document par mot de passe","Réduire la taille du fichier","Harmoniser la mise en forme et générer automatiquement une table des matières"],a:3,e:"Modifier un style met à jour d'un coup tous les titres concernés ; les styles structurent aussi le document pour l'accessibilité.",s:"Banque numérique"},
{id:"nu2-045",t:"num",q:"Qu'est-ce que le publipostage dans un traitement de texte ?",o:["La publication d'un document sur un site","L'envoi d'un document par la poste","La fusion d'un document type avec une liste de données pour produire des courriers personnalisés","La conversion d'un document en PDF"],a:2,e:"Exemple : une lettre type fusionnée avec un fichier d'adresses issu d'un tableur.",u:["https://fr.wikipedia.org/wiki/Publipostage"],s:"Banque numérique"},
{id:"nu2-046",t:"num",q:"Qu'est-ce que le PDF/A ?",o:["Un PDF modifiable par tous","Une version normalisée du PDF destinée à l'archivage à long terme","Un PDF protégé par mot de passe","Un PDF réservé aux images"],a:1,e:"Norme ISO 19005 : le fichier embarque tout ce qu'il faut (polices…) pour rester lisible à l'identique.",u:["https://fr.wikipedia.org/wiki/PDF/A"],s:"Banque numérique"},
{id:"nu2-047",t:"num",q:"Qu'est-ce qui distingue une image vectorielle d'une image matricielle (bitmap) ?",o:["Elle est décrite par des formes géométriques et peut être agrandie sans perte de qualité","Elle est toujours en noir et blanc","Elle ne peut pas être imprimée","Elle est composée de pixels plus nombreux"],a:0,e:"Une image matricielle est une grille de pixels : agrandie, elle se pixellise. Les logos sont souvent vectoriels.",u:["https://fr.wikipedia.org/wiki/Image_vectorielle","https://fr.wikipedia.org/wiki/Image_matricielle"],s:"Banque numérique"},
{id:"nu2-048",t:"num",q:"Lequel de ces formats est un format d'image vectorielle ?",o:["JPEG","PNG","GIF","SVG"],a:3,e:"SVG (Scalable Vector Graphics) ; JPEG, PNG et GIF sont des formats matriciels.",u:["https://fr.wikipedia.org/wiki/Scalable_Vector_Graphics"],s:"Banque numérique"},
{id:"nu2-049",t:"num",q:"Une image de 1 920 × 1 080 pixels contient environ :",o:["200 000 pixels","2 millions de pixels","20 millions de pixels","3 000 pixels"],a:1,e:"1 920 × 1 080 = 2 073 600 pixels (format « Full HD »).",u:["https://fr.wikipedia.org/wiki/Pixel"],s:"Banque numérique"},
{id:"nu2-050",t:"num",q:"Que mesure une résolution exprimée en ppp (points par pouce, dpi en anglais) ?",o:["La densité de points d'une image imprimée ou numérisée","La vitesse d'une imprimante","Le nombre de couleurs d'une image","La taille du fichier"],a:0,e:"Un pouce mesure 2,54 cm ; 300 ppp est une valeur courante pour l'impression.",u:["https://fr.wikipedia.org/wiki/Point_par_pouce"],s:"Banque numérique"},
{id:"nu2-051",t:"num",q:"Lequel de ces formats audio utilise une compression sans perte ?",o:["MP3","AAC","FLAC","Opus"],a:2,e:"FLAC (Free Lossless Audio Codec) restitue exactement le son d'origine ; MP3, AAC et Opus suppriment des informations peu audibles.",u:["https://fr.wikipedia.org/wiki/Free_Lossless_Audio_Codec"],s:"Banque numérique"},
{id:"nu2-052",t:"num",q:"En France, combien de temps les droits patrimoniaux d'un auteur durent-ils après sa mort ?",o:["20 ans","50 ans","70 ans","100 ans"],a:2,e:"Ils courent l'année civile du décès et les 70 années suivantes ; l'œuvre entre ensuite dans le domaine public.",u:["https://fr.wikipedia.org/wiki/Droit_d'auteur_en_France"],s:"Code de la propriété intellectuelle"},
{id:"nu2-053",t:"num",q:"Quelle est la caractéristique du droit moral de l'auteur en droit français ?",o:["Il peut être vendu à un éditeur","Il expire 70 ans après la mort de l'auteur","Il est perpétuel, inaliénable et imprescriptible","Il ne concerne que les œuvres musicales"],a:2,e:"Il protège notamment le droit au nom (paternité) et le respect de l'intégrité de l'œuvre.",u:["https://fr.wikipedia.org/wiki/Droit_moral"],s:"Code de la propriété intellectuelle"},
{id:"nu2-054",t:"num",q:"Peut-on réutiliser librement une photo trouvée sur Internet ?",o:["Oui, tout ce qui est en ligne est libre de droits","Oui, à condition de la recadrer","Non, sauf si elle est en noir et blanc","Non en principe : elle est protégée par le droit d'auteur, sauf licence ou exception le permettant"],a:3,e:"Il faut l'autorisation de l'auteur, une licence libre (Creative Commons…) ou une exception légale.",s:"Banque numérique"},
{id:"nu2-055",t:"num",q:"Quelle exception au droit d'auteur permet de reproduire un bref extrait d'une œuvre, à condition d'indiquer l'auteur et la source ?",o:["Le droit de courte citation","La copie privée","Le droit de suite","L'exception de parodie"],a:0,e:"La citation doit être courte et justifiée par un but critique, pédagogique, scientifique ou d'information.",u:["https://fr.wikipedia.org/wiki/Droit_de_citation"],s:"Banque numérique"},
{id:"nu2-056",t:"num",q:"Une image est publiée sous licence Creative Commons CC BY-NC. Que ne peut-on pas faire ?",o:["La partager en citant l'auteur","La modifier en citant l'auteur","L'imprimer pour un usage personnel","L'utiliser à des fins commerciales"],a:3,e:"BY : citer l'auteur ; NC : pas d'usage commercial. Sans la mention ND (pas de modification), les adaptations sont permises.",u:["https://fr.wikipedia.org/wiki/Licence_Creative_Commons"],s:"Banque numérique"},
{id:"nu2-057",t:"num",q:"Que signifie la mention « SA » (Share Alike) d'une licence Creative Commons ?",o:["Sans auteur","Partage dans les mêmes conditions : les œuvres dérivées doivent être diffusées sous la même licence","Usage strictement scolaire","Signature électronique obligatoire"],a:1,e:"C'est une application du principe du copyleft ; les textes de Wikipédia sont sous licence CC BY-SA.",u:["https://fr.wikipedia.org/wiki/Licence_Creative_Commons"],s:"Banque numérique"},
{id:"nu2-058",t:"num",q:"Que permet l'outil CC0 de Creative Commons ?",o:["Interdire toute copie","Réserver l'œuvre aux administrations","Imposer la citation de l'auteur","Renoncer à ses droits pour placer l'œuvre au plus près du domaine public"],a:3,e:"L'œuvre peut alors être réutilisée sans condition, même sans citer l'auteur.",u:["https://fr.wikipedia.org/wiki/CC0"],s:"Banque numérique"},
{id:"nu2-059",t:"num",q:"Qu'est-ce que le copyleft ?",o:["Le principe selon lequel les versions modifiées d'une œuvre libre doivent rester sous la même licence libre","L'interdiction de copier un logiciel","Une protection contre les captures d'écran","Le droit exclusif de l'éditeur"],a:0,e:"La licence GNU GPL en est l'exemple type pour les logiciels.",u:["https://fr.wikipedia.org/wiki/Copyleft"],s:"Banque numérique"},
{id:"nu2-060",t:"num",q:"Pour qu'une image insérée dans un document ou une page web soit accessible à une personne aveugle, il faut :",o:["L'agrandir","Lui associer un texte alternatif décrivant son contenu","La convertir en noir et blanc","La placer en arrière-plan"],a:1,e:"Les lecteurs d'écran lisent ce texte ; c'est l'un des critères du RGAA.",s:"Banque numérique"},

// --- Matériel et réseaux ---
{id:"nu2-061",t:"num",q:"Selon les préfixes décimaux du Système international, combien d'octets compte un kilooctet (ko) ?",o:["8","100","1 000","1 024"],a:2,e:"1 ko = 1 000 octets ; 1 024 octets forment un kibioctet (Kio), préfixe binaire. L'usage courant confond souvent les deux.",u:["https://fr.wikipedia.org/wiki/Préfixe_binaire"],s:"Banque numérique"},
{id:"nu2-062",t:"num",q:"Quel classement d'unités est rangé dans l'ordre croissant ?",o:["Mégaoctet < kilooctet < gigaoctet < téraoctet","Kilooctet < mégaoctet < gigaoctet < téraoctet","Kilooctet < gigaoctet < mégaoctet < téraoctet","Téraoctet < gigaoctet < mégaoctet < kilooctet"],a:1,e:"Kilo (mille), méga (million), giga (milliard), téra (mille milliards).",u:["https://fr.wikipedia.org/wiki/Octet"],s:"Banque numérique"},
{id:"nu2-063",t:"num",q:"Combien de photos de 4 Mo peut-on stocker sur une carte mémoire de 1 Go (1 Go = 1 000 Mo) ?",o:["25","250","400","4 000"],a:1,e:"1 000 ÷ 4 = 250 photos.",s:"Banque numérique"},
{id:"nu2-064",t:"num",q:"Avec un débit réel constant de 100 Mbit/s, combien de temps faut-il au minimum pour télécharger un fichier de 100 Mo ?",o:["1 seconde","8 secondes","80 secondes","100 secondes"],a:1,e:"Le débit s'exprime en bits par seconde : 100 Mo = 800 Mbit (1 octet = 8 bits) ; 800 ÷ 100 = 8 s.",u:["https://fr.wikipedia.org/wiki/Débit_binaire"],s:"Banque numérique"},
{id:"nu2-065",t:"num",q:"Quel est le principal avantage d'un SSD par rapport à un disque dur mécanique ?",o:["Il est toujours moins cher au gigaoctet","Il efface les données à chaque extinction","Il ne nécessite pas de système d'exploitation","Il est plus rapide et dépourvu de pièces mobiles"],a:3,e:"Mémoire flash, comme une clé USB : il conserve les données sans alimentation, contrairement à la RAM.",u:["https://fr.wikipedia.org/wiki/Solid-state_drive"],s:"Banque numérique"},
{id:"nu2-066",t:"num",q:"Quel est le rôle du BIOS ou de l'UEFI d'un ordinateur ?",o:["Protéger contre les virus","Gérer la messagerie","Compresser les fichiers","Démarrer l'ordinateur et initialiser le matériel avant de lancer le système d'exploitation"],a:3,e:"C'est un micrologiciel stocké sur la carte mère ; l'UEFI a succédé au BIOS.",u:["https://fr.wikipedia.org/wiki/BIOS_(informatique)"],s:"Banque numérique"},
{id:"nu2-067",t:"num",q:"Lequel de ces périphériques est un périphérique d'entrée ?",o:["L'imprimante","L'écran","Le scanner","Les haut-parleurs"],a:2,e:"Il fait entrer des données dans l'ordinateur, comme le clavier, la souris ou le micro ; imprimante, écran et haut-parleurs sont des périphériques de sortie.",u:["https://fr.wikipedia.org/wiki/Périphérique_informatique"],s:"Banque numérique"},
{id:"nu2-068",t:"num",q:"Quel est le rôle du DNS (système de noms de domaine) ?",o:["Chiffrer les échanges","Bloquer les publicités","Attribuer les adresses électroniques","Traduire les noms de domaine (ex. impots.gouv.fr) en adresses IP"],a:3,e:"C'est l'« annuaire » d'Internet : il évite d'avoir à retenir des adresses IP.",u:["https://fr.wikipedia.org/wiki/Domain_Name_System"],s:"Banque numérique"},
{id:"nu2-069",t:"num",q:"Dans l'adresse https://www.impots.gouv.fr/particulier, que désigne « .fr » ?",o:["Le protocole","Le chemin vers la page","Le domaine de premier niveau (ici, national)","Le nom du serveur de messagerie"],a:2,e:"« https » est le protocole, « impots.gouv.fr » le nom de domaine, « /particulier » le chemin de la page.",u:["https://fr.wikipedia.org/wiki/Domaine_de_premier_niveau","https://fr.wikipedia.org/wiki/Uniform_Resource_Locator"],s:"Banque numérique"},
{id:"nu2-070",t:"num",q:"Que signale l'extension « .gouv.fr » dans l'adresse d'un site ?",o:["Un site commercial agréé par l'État","Un site officiel du Gouvernement ou d'une administration de l'État, cette extension leur étant réservée","Un site hébergé gratuitement","Un site d'une collectivité étrangère"],a:1,e:"Un site comme « impots-gouv-remboursement.com » n'est pas officiel : réflexe utile contre l'hameçonnage.",u:["https://fr.wikipedia.org/wiki/.gouv.fr"],s:"Banque numérique"},
{id:"nu2-071",t:"num",q:"Comment la fibre optique transmet-elle les données ?",o:["Par des impulsions lumineuses dans un fil de verre ou de plastique","Par la paire de cuivre de la ligne téléphonique","Uniquement par satellite","Par ondes radio"],a:0,e:"Elle offre des débits bien supérieurs à l'ADSL, qui utilise la ligne téléphonique en cuivre.",u:["https://fr.wikipedia.org/wiki/Fibre_optique"],s:"Banque numérique"},
{id:"nu2-072",t:"num",q:"Qu'apporte principalement la 5G par rapport à la 4G ?",o:["Une connexion par câble","La suppression des antennes relais","Des débits plus élevés, une latence plus faible et davantage d'objets connectés simultanément","Une couverture limitée aux zones rurales"],a:2,e:"Cinquième génération de réseaux mobiles, déployée en France à partir de 2020.",u:["https://fr.wikipedia.org/wiki/5G"],s:"Banque numérique"},
{id:"nu2-073",t:"num",q:"Pourquoi le protocole IPv6 a-t-il été développé ?",o:["Pour accélérer l'affichage des vidéos","Pour remplacer le DNS","Pour pallier la pénurie d'adresses IPv4, grâce à des adresses de 128 bits au lieu de 32","Pour chiffrer automatiquement les courriels"],a:2,e:"IPv4 n'offre qu'environ 4,3 milliards d'adresses, insuffisantes face à la multiplication des appareils connectés.",u:["https://fr.wikipedia.org/wiki/IPv6"],s:"Banque numérique"},
{id:"nu2-074",t:"num",q:"Laquelle de ces adresses est une adresse IPv4 valide ?",o:["192.168.1.300","192.168.1","192.168.1.10","192.168.1.10.5"],a:2,e:"Une adresse IPv4 compte quatre nombres de 0 à 255 séparés par des points.",u:["https://fr.wikipedia.org/wiki/IPv4"],s:"Banque numérique"},
{id:"nu2-075",t:"num",q:"Quel protocole est utilisé pour envoyer des courriels ?",o:["IMAP","POP3","FTP","SMTP"],a:3,e:"SMTP (Simple Mail Transfer Protocol) achemine les messages ; IMAP et POP3 servent à les relever.",u:["https://fr.wikipedia.org/wiki/Simple_Mail_Transfer_Protocol"],s:"Banque numérique"},
{id:"nu2-076",t:"num",q:"Quel protocole de réception laisse les courriels sur le serveur et synchronise plusieurs appareils ?",o:["POP3","IMAP","FTP","DNS"],a:1,e:"POP3 rapatrie en général les messages sur un seul appareil ; FTP sert au transfert de fichiers.",u:["https://fr.wikipedia.org/wiki/Internet_Message_Access_Protocol"],s:"Banque numérique"},
{id:"nu2-077",t:"num",q:"Quelle est la différence entre Internet et le Web ?",o:["Ce sont deux noms pour la même chose","Le Web est le réseau physique, Internet un service qui l'utilise","Internet est le réseau mondial ; le Web est un service de pages reliées par des liens hypertextes qui fonctionne sur Internet","Internet est réservé aux entreprises"],a:2,e:"La messagerie électronique ou le transfert de fichiers sont d'autres services d'Internet.",u:["https://fr.wikipedia.org/wiki/World_Wide_Web"],s:"Banque numérique"},
{id:"nu2-078",t:"num",q:"Qui a inventé le World Wide Web au CERN, à partir de 1989 ?",o:["Bill Gates","Vinton Cerf","Tim Berners-Lee","Louis Pouzin"],a:2,e:"Vinton Cerf est l'un des pères de TCP/IP ; Louis Pouzin a conçu le réseau français Cyclades.",u:["https://fr.wikipedia.org/wiki/Tim_Berners-Lee"],s:"Banque numérique"},

// --- Sécurité ---
{id:"nu2-079",t:"num",q:"Qu'est-ce qui caractérise un ver informatique ?",o:["Il se propage seul d'un ordinateur à l'autre via le réseau, sans action de l'utilisateur","Il ne peut infecter que les clés USB","Il affiche uniquement des publicités","C'est un logiciel de sauvegarde"],a:0,e:"Le virus, lui, a besoin d'un fichier ou d'un programme hôte que l'on exécute.",u:["https://fr.wikipedia.org/wiki/Ver_informatique"],s:"Banque numérique"},
{id:"nu2-080",t:"num",q:"Qu'est-ce qui caractérise un virus informatique ?",o:["Il se loge dans un fichier ou un programme hôte et se propage lorsque celui-ci est exécuté","C'est un défaut matériel de l'ordinateur","Il ne peut pas se propager","Il est sans danger pour les données"],a:0,e:"D'où la règle : ne pas ouvrir de pièce jointe ou de programme d'origine douteuse.",u:["https://fr.wikipedia.org/wiki/Virus_informatique"],s:"Banque numérique"},
{id:"nu2-081",t:"num",q:"Qu'est-ce qu'un botnet ?",o:["Un robot conversationnel","Un réseau social professionnel","Un moteur de recherche","Un réseau d'appareils infectés (« machines zombies ») contrôlés à distance par un attaquant"],a:3,e:"Il sert notamment à envoyer du spam ou à mener des attaques par déni de service distribué.",u:["https://fr.wikipedia.org/wiki/Botnet"],s:"Banque numérique"},
{id:"nu2-082",t:"num",q:"Qu'est-ce qu'une attaque par déni de service distribué (DDoS) ?",o:["Le vol de mots de passe","La saturation d'un service par un afflux de requêtes provenant de nombreuses machines, pour le rendre indisponible","Le chiffrement des données contre rançon","L'envoi de faux courriels"],a:1,e:"Elle vise la disponibilité du service, pas le vol de données.",u:["https://fr.wikipedia.org/wiki/Attaque_par_déni_de_service","https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/attaque-en-deni-de-service-ddos"],s:"Banque numérique"},
{id:"nu2-083",t:"num",q:"Qu'est-ce que l'ingénierie sociale en cybersécurité ?",o:["La conception de réseaux sociaux","La sociologie des usages du numérique","La manipulation psychologique d'une personne pour obtenir des informations ou une action (clic, virement, mot de passe)","Le recrutement d'informaticiens"],a:2,e:"Elle exploite la confiance, l'urgence ou la peur ; l'hameçonnage et la fraude au président en relèvent.",u:["https://fr.wikipedia.org/wiki/Ingénierie_sociale_(sécurité_de_l'information)"],s:"Banque numérique"},
{id:"nu2-084",t:"num",q:"En quoi consiste la « fraude au président » ?",o:["Un escroc se fait passer pour un dirigeant afin d'obtenir un virement urgent et confidentiel","Un dirigeant détourne des fonds publics","Un pirate attaque le site de l'Élysée","Un employé vole du matériel informatique"],a:0,e:"Parade : vérifier toute demande inhabituelle par un autre canal et respecter les procédures de validation des paiements.",s:"Banque numérique"},
{id:"nu2-085",t:"num",q:"Comment appelle-t-on l'hameçonnage par SMS ?",o:["Le vishing","Le smishing","Le pharming","Le spoofing"],a:1,e:"Vishing : par appel vocal ; spoofing : usurpation d'une adresse ou d'un numéro. Les SMS frauduleux se signalent au 33700.",u:["https://fr.wikipedia.org/wiki/Hameçonnage"],s:"Banque numérique"},
{id:"nu2-086",t:"num",q:"L'administration fiscale peut-elle vous demander par courriel ou SMS votre numéro de carte bancaire pour un remboursement ?",o:["Oui, pour accélérer le remboursement","Oui, si le message porte le logo de la DGFiP","Non, jamais : un tel message est une tentative d'hameçonnage","Oui, une fois par an"],a:2,e:"En cas de doute, ne pas cliquer et se connecter directement à son espace sur impots.gouv.fr.",u:["https://www.impots.gouv.fr/courriels-et-sms-frauduleux-hameconnage-ou-phishing"],s:"impots.gouv.fr"},
{id:"nu2-087",t:"num",q:"Vous recevez un lien vers « impots-gouv-fr.com ». Que pouvez-vous en conclure ?",o:["C'est un site officiel de la DGFiP","Ce n'est pas un site officiel : celui de l'administration fiscale est impots.gouv.fr","C'est le site de secours de la DGFiP","C'est le site officiel de paiement des amendes"],a:1,e:"Les fraudeurs imitent les noms officiels ; l'extension .gouv.fr est réservée aux services de l'État.",u:["https://www.impots.gouv.fr/courriels-et-sms-frauduleux-hameconnage-ou-phishing"],s:"impots.gouv.fr"},
{id:"nu2-088",t:"num",q:"Quel est l'intérêt d'un gestionnaire de mots de passe ?",o:["Utiliser le même mot de passe partout","Stocker de façon chiffrée des mots de passe robustes et différents pour chaque compte, protégés par un mot de passe maître","Partager ses mots de passe sur les réseaux sociaux","Supprimer la double authentification"],a:1,e:"Il ne reste qu'un seul mot de passe, robuste, à retenir.",u:["https://fr.wikipedia.org/wiki/Gestionnaire_de_mots_de_passe","https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/mots-de-passe"],s:"Banque numérique"},
{id:"nu2-089",t:"num",q:"Pourquoi ne faut-il pas utiliser le même mot de passe pour plusieurs comptes ?",o:["Parce que si un service est piraté, tous les comptes protégés par ce mot de passe deviennent vulnérables","Parce que les sites l'interdisent","Parce que cela ralentit la connexion","Parce que le mot de passe expire plus vite"],a:0,e:"Les attaquants testent automatiquement les identifiants volés sur de nombreux sites.",u:["https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/mots-de-passe"],s:"Banque numérique"},
{id:"nu2-090",t:"num",q:"Selon la recommandation de la CNIL, un mot de passe utilisé seul doit au minimum compter :",o:["6 caractères","8 caractères, dont un chiffre","10 chiffres","12 caractères mêlant majuscules, minuscules, chiffres et caractères spéciaux"],a:3,e:"La CNIL admet aussi 14 caractères sans caractère spécial obligatoire, ou une phrase de passe d'au moins 7 mots.",u:["https://www.cnil.fr/fr/mots-de-passe-recommandations-pour-maitriser-sa-securite"],s:"CNIL"},
{id:"nu2-091",t:"num",q:"Laquelle de ces combinaisons constitue une authentification multifacteur ?",o:["Un mot de passe et une question secrète","Deux mots de passe différents","Un mot de passe et un code reçu sur son téléphone","Un identifiant et un mot de passe"],a:2,e:"Il faut deux catégories de facteurs : ce que l'on sait, ce que l'on possède, ce que l'on est. Mot de passe et question secrète relèvent tous deux de « ce que l'on sait ».",u:["https://fr.wikipedia.org/wiki/Authentification_multifacteur"],s:"Banque numérique"},
{id:"nu2-092",t:"num",q:"Une empreinte digitale utilisée pour s'authentifier relève de quelle catégorie de facteur ?",o:["Ce que l'on sait","Ce que l'on possède","Ce que l'on a déclaré","Ce que l'on est"],a:3,e:"Facteur biométrique ; le mot de passe est ce que l'on sait, le téléphone ou la carte ce que l'on possède.",u:["https://fr.wikipedia.org/wiki/Authentification_multifacteur"],s:"Banque numérique"},
{id:"nu2-093",t:"num",q:"Pourquoi faut-il installer rapidement les mises à jour de sécurité ?",o:["Pour changer l'apparence du logiciel","Pour libérer de l'espace disque","Parce qu'elles corrigent des failles que des attaquants peuvent exploiter","Parce qu'elles suppriment les anciennes sauvegardes"],a:2,e:"Système, navigateur, applications : un logiciel non mis à jour est une porte d'entrée.",u:["https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/mises-a-jour"],s:"Cybermalveillance.gouv.fr"},
{id:"nu2-094",t:"num",q:"Qu'est-ce qu'une vulnérabilité « zero day » (jour zéro) ?",o:["Une faille exploitée avant que l'éditeur n'ait publié de correctif","Un virus qui s'active le premier jour du mois","Un logiciel sans aucune faille","Une sauvegarde quotidienne"],a:0,e:"L'éditeur a « zéro jour » pour réagir : la faille est déjà utilisée par des attaquants.",s:"Banque numérique"},
{id:"nu2-095",t:"num",q:"Selon cybermalveillance.gouv.fr, que faut-il faire en cas d'attaque par rançongiciel ?",o:["Payer rapidement la rançon pour récupérer les données","Désactiver l'antivirus","Effacer immédiatement toutes les traces de l'attaque","Débrancher les appareils du réseau, ne pas payer la rançon et déposer plainte"],a:3,e:"Payer ne garantit pas la récupération des données et finance les criminels ; il faut conserver les preuves.",u:["https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/rancongiciels-ransomwares"],s:"Cybermalveillance.gouv.fr"},
{id:"nu2-096",t:"num",q:"En chiffrement asymétrique, avec quelle clé chiffre-t-on un message destiné à une personne ?",o:["Avec sa propre clé privée","Avec la clé publique du destinataire","Avec la clé privée du destinataire","Sans aucune clé"],a:1,e:"Seul le destinataire, qui détient la clé privée correspondante, peut le déchiffrer. En chiffrement symétrique, une même clé sert à chiffrer et déchiffrer.",u:["https://fr.wikipedia.org/wiki/Cryptographie_asymétrique"],s:"Banque numérique"},
{id:"nu2-097",t:"num",q:"Qu'atteste le certificat électronique d'un site en HTTPS ?",o:["Que le site ne contient aucune arnaque","Que le site est hébergé en France","Le lien entre le nom de domaine et une clé publique, garanti par une autorité de certification","Que le site a été validé par la CNIL"],a:2,e:"Il permet d'établir une connexion chiffrée avec le bon serveur, mais ne dit rien de l'honnêteté du site.",u:["https://fr.wikipedia.org/wiki/Certificat_électronique"],s:"Banque numérique"},
{id:"nu2-098",t:"num",q:"Le cadenas affiché dans la barre d'adresse garantit-il qu'un site est honnête ?",o:["Oui, il est délivré après un contrôle par l'État","Non : il signale seulement une connexion chiffrée, et un site frauduleux peut aussi l'afficher","Oui, s'il est de couleur verte","Oui, pour les sites en .com"],a:1,e:"Il faut aussi vérifier l'adresse exacte du site.",u:["https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/hameconnage-phishing"],s:"Banque numérique"},
{id:"nu2-099",t:"num",q:"Que signifie un chiffrement « de bout en bout » dans une messagerie ?",o:["Que seuls l'émetteur et le destinataire peuvent lire les messages, pas même le fournisseur du service","Que les messages sont sauvegardés en double","Que le message est envoyé en plusieurs morceaux","Que la messagerie est gratuite"],a:0,e:"Le message est chiffré sur l'appareil de l'émetteur et déchiffré seulement sur celui du destinataire.",u:["https://fr.wikipedia.org/wiki/Chiffrement_de_bout_en_bout"],s:"Banque numérique"},
{id:"nu2-100",t:"num",q:"Quelle précaution prendre sur un réseau Wi-Fi public (gare, café) ?",o:["Éviter les opérations sensibles ou passer par un VPN","Y effectuer de préférence ses opérations bancaires","Désactiver le pare-feu pour faciliter la connexion","Partager ses dossiers avec les autres usagers"],a:0,e:"Un réseau ouvert peut être espionné, voire imité par un faux point d'accès.",s:"Banque numérique"},
{id:"nu2-101",t:"num",q:"Que faire d'une clé USB trouvée dans un parking ou un couloir ?",o:["Ne pas la brancher et la remettre au service informatique ou de sécurité","La brancher pour identifier son propriétaire","La formater sur son poste puis la réutiliser","L'insérer sur un ordinateur en libre-service"],a:0,e:"Elle peut contenir un logiciel malveillant qui s'exécute dès la connexion.",s:"Banque numérique"},
{id:"nu2-102",t:"num",q:"À quelle structure l'ANSSI est-elle rattachée ?",o:["Au ministère de l'Intérieur","Au secrétariat général de la défense et de la sécurité nationale (SGDSN), placé auprès du Premier ministre","À la CNIL","Au ministère de l'Économie"],a:1,e:"Agence nationale de la sécurité des systèmes d'information, autorité nationale de cybersécurité.",u:["https://fr.wikipedia.org/wiki/Agence_nationale_de_la_sécurité_des_systèmes_d'information"],s:"Banque numérique"},
{id:"nu2-103",t:"num",q:"Qu'est-ce que le CERT-FR ?",o:["Le centre gouvernemental de veille, d'alerte et de réponse aux attaques informatiques, au sein de l'ANSSI","Un certificat de conformité au RGPD","Un service de la CNIL","Une norme de chiffrement"],a:0,e:"Il publie notamment des alertes et des avis de sécurité sur les vulnérabilités.",u:["https://fr.wikipedia.org/wiki/CERT-FR"],s:"Banque numérique"},
{id:"nu2-104",t:"num",q:"Qu'est-ce que 17Cyber, lancé en décembre 2024 ?",o:["Un service en ligne d'assistance aux victimes de cybermalveillance, avec mise en relation possible avec un policier ou un gendarme","Le numéro des pompiers pour les incendies d'origine électrique","Une unité militaire de cyberdéfense","Un antivirus fourni gratuitement par l'État"],a:0,e:"Accessible sur 17cyber.gouv.fr, il est porté par cybermalveillance.gouv.fr, la police et la gendarmerie nationales. Ce n'est pas un numéro d'urgence : en cas d'urgence, on compose le 17 ou le 112.",u:["https://17cyber.gouv.fr/"],s:"Banque numérique"},
{id:"nu2-105",t:"num",q:"Quel téléservice permet de porter plainte en ligne pour certaines escroqueries sur Internet (faux site de vente, chantage en ligne…) ?",o:["PHAROS","THESEE","Signal Spam","Tchap"],a:1,e:"Traitement harmonisé des enquêtes et signalements pour les e-escroqueries, ouvert en 2022, accessible via service-public.fr et FranceConnect.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/N31138"],s:"Service-Public.fr"},
{id:"nu2-106",t:"num",q:"Quel téléservice permet de signaler l'utilisation frauduleuse de sa carte bancaire sur Internet, lorsque l'on a toujours la carte en sa possession ?",o:["Perceval","PHAROS","Signal Spam","FranceConnect"],a:0,e:"Il faut d'abord faire opposition auprès de sa banque ; le récépissé obtenu aide au remboursement.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/R46526"],s:"Service-Public.fr"},
{id:"nu2-107",t:"num",q:"Pourquoi conserver une copie de sauvegarde déconnectée du réseau ?",o:["Pour accélérer l'ordinateur","Pour économiser de l'électricité","Parce que le RGPD l'impose dans tous les cas","Pour qu'elle ne puisse pas être chiffrée par un rançongiciel qui infecte le réseau"],a:3,e:"Une sauvegarde accessible en permanence peut être atteinte en même temps que les données d'origine.",u:["https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/sauvegardes"],s:"Cybermalveillance.gouv.fr"},
{id:"nu2-108",t:"num",q:"Une fenêtre bloque votre navigateur et vous demande d'appeler d'urgence le « support Microsoft ». De quoi s'agit-il le plus probablement ?",o:["D'une alerte officielle de Windows","D'une arnaque au faux support technique","D'une mise à jour obligatoire","D'un message de la CNIL"],a:1,e:"Ne pas appeler, ne pas payer ; fermer le navigateur (au besoin en le forçant) et conserver des preuves.",u:["https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/arnaques-au-faux-support-technique"],s:"Cybermalveillance.gouv.fr"},
{id:"nu2-109",t:"num",q:"Qu'est-ce que la qualification SecNumCloud ?",o:["Un label de sobriété énergétique des centres de données","Un cloud réservé à la DGFiP","Une norme de compression","Une qualification de l'ANSSI attestant un haut niveau de sécurité d'une offre d'informatique en nuage"],a:3,e:"Elle est exigée pour héberger les données sensibles de l'État dans un cloud commercial.",u:["https://fr.wikipedia.org/wiki/SecNumCloud"],s:"Banque numérique"},
{id:"nu2-110",t:"num",q:"Qu'est-ce qu'un logiciel espion (spyware) ?",o:["Un antivirus de nouvelle génération","Un logiciel qui collecte des informations sur l'utilisateur à son insu","Un pare-feu matériel","Un logiciel de sauvegarde"],a:1,e:"L'enregistreur de frappe (keylogger), qui capte les touches tapées, en est une variante.",u:["https://fr.wikipedia.org/wiki/Logiciel_espion"],s:"Banque numérique"},

// --- Données personnelles, RGPD, CNIL ---
{id:"nu2-111",t:"num",q:"Au sens du RGPD, qu'est-ce qu'une donnée à caractère personnel ?",o:["Une donnée confidentielle d'une entreprise","Toute information se rapportant à une personne physique identifiée ou identifiable, directement ou indirectement","Uniquement le nom et le prénom","Uniquement les données de santé"],a:1,e:"Exemples : nom, numéro de téléphone, photo, adresse IP, numéro fiscal, voix…",u:["https://www.cnil.fr/fr/definition/donnee-personnelle"],s:"RGPD, art. 4"},
{id:"nu2-112",t:"num",q:"Une adresse IP est-elle une donnée personnelle ?",o:["Non, c'est une donnée purement technique","Seulement si elle est publiée sur Internet","Seulement pour les comptes professionnels","Oui, car elle peut permettre d'identifier indirectement une personne"],a:3,e:"Une donnée est personnelle dès lors qu'elle permet d'identifier une personne, même indirectement (par recoupement).",u:["https://www.cnil.fr/fr/definition/donnee-personnelle"],s:"RGPD, art. 4"},
{id:"nu2-113",t:"num",q:"Laquelle de ces informations est une donnée sensible au sens du RGPD ?",o:["L'adresse postale","Le numéro de téléphone","L'appartenance syndicale","La date de naissance"],a:2,e:"Données sensibles : origine raciale ou ethnique, opinions politiques, convictions religieuses ou philosophiques, appartenance syndicale, données génétiques, biométriques, de santé, vie ou orientation sexuelle. Leur traitement est interdit sauf exceptions.",u:["https://www.cnil.fr/fr/definition/donnee-sensible"],s:"RGPD, art. 9"},
{id:"nu2-114",t:"num",q:"Au sens du RGPD, qui est le responsable de traitement ?",o:["L'informaticien qui gère le serveur","Le délégué à la protection des données","La CNIL","La personne ou l'organisme qui détermine les finalités et les moyens du traitement"],a:3,e:"Le sous-traitant, lui, traite les données pour le compte du responsable et sur ses instructions.",u:["https://www.cnil.fr/fr/definition/responsable-de-traitement","https://www.cnil.fr/fr/definition/sous-traitant"],s:"RGPD, art. 4"},
{id:"nu2-115",t:"num",q:"Combien de bases légales (fondements de licéité) le RGPD prévoit-il pour un traitement de données ?",o:["Deux","Quatre","Six","Dix"],a:2,e:"Consentement, contrat, obligation légale, sauvegarde des intérêts vitaux, mission d'intérêt public, intérêts légitimes.",u:["https://www.cnil.fr/fr/les-bases-legales"],s:"RGPD, art. 6"},
{id:"nu2-116",t:"num",q:"Quelle base légale une autorité publique ne peut-elle pas invoquer pour les traitements effectués dans l'exécution de ses missions ?",o:["L'obligation légale","La mission d'intérêt public","La sauvegarde des intérêts vitaux","L'intérêt légitime"],a:3,e:"Le RGPD l'exclut expressément pour les autorités publiques dans l'exercice de leurs missions.",u:["https://www.cnil.fr/fr/les-bases-legales/interet-legitime"],s:"RGPD, art. 6"},
{id:"nu2-117",t:"num",q:"Selon le RGPD, le consentement doit être :",o:["Tacite et général","Libre, spécifique, éclairé et univoque","Écrit et signé devant témoin","Présumé tant que la personne ne s'y oppose pas"],a:1,e:"Il résulte d'une déclaration ou d'un acte positif clair.",u:["https://www.cnil.fr/fr/les-bases-legales/consentement"],s:"RGPD, art. 4 et 7"},
{id:"nu2-118",t:"num",q:"Une case pré-cochée sur un formulaire en ligne vaut-elle consentement au sens du RGPD ?",o:["Non, le consentement suppose un acte positif clair de la personne","Oui, si l'internaute ne la décoche pas","Oui, pour les cookies publicitaires","Oui, si la case figure en bas de page"],a:0,e:"La CJUE l'a jugé dans l'arrêt Planet49 (2019).",u:["https://www.cnil.fr/fr/les-bases-legales/consentement"],s:"Banque numérique"},
{id:"nu2-119",t:"num",q:"Une personne peut-elle retirer son consentement à un traitement de données ?",o:["Non, il est définitif","Oui, mais seulement après un an","Oui, à tout moment, et cela doit être aussi simple que de le donner","Oui, uniquement par lettre recommandée"],a:2,e:"Le retrait ne remet pas en cause la licéité du traitement effectué auparavant.",s:"RGPD, art. 7"},
{id:"nu2-120",t:"num",q:"Pour la prospection commerciale, une personne peut-elle s'opposer à l'utilisation de ses données ?",o:["Seulement avec l'accord de la CNIL","Seulement si elle justifie d'un motif légitime","Non, la prospection est libre","Oui, à tout moment et sans avoir à se justifier"],a:3,e:"Pour les autres traitements, l'opposition doit en principe être motivée par la situation particulière de la personne.",u:["https://www.cnil.fr/fr/comprendre-mes-droits/le-droit-dopposition-refuser-lutilisation-de-vos-donnees"],s:"RGPD, art. 21"},
{id:"nu2-121",t:"num",q:"Dans quel délai un organisme doit-il en principe répondre à une demande d'exercice des droits (accès, rectification…) ?",o:["Huit jours","Un mois, prolongeable de deux mois si nécessaire","Six mois","Un an"],a:1,e:"La réponse est en principe gratuite.",u:["https://www.cnil.fr/fr/mes-demarches/les-droits-pour-maitriser-vos-donnees-personnelles"],s:"RGPD, art. 12"},
{id:"nu2-122",t:"num",q:"Quel droit le RGPD reconnaît-il face aux décisions automatisées ?",o:["L'interdiction de tout algorithme","Le droit de ne pas faire l'objet d'une décision fondée exclusivement sur un traitement automatisé produisant des effets juridiques, sauf exceptions","L'obligation de publier tous les codes sources","La gratuité des services en ligne"],a:1,e:"La personne peut notamment obtenir une intervention humaine et contester la décision.",s:"RGPD, art. 22"},
{id:"nu2-123",t:"num",q:"Que signifie le principe de responsabilité (accountability) du RGPD ?",o:["La CNIL est responsable des fuites de données","Chaque salarié est pénalement responsable des traitements","Les données doivent être inscrites au bilan comptable","Le responsable de traitement doit pouvoir démontrer à tout moment sa conformité"],a:3,e:"Les formalités préalables (déclarations à la CNIL) ont été largement remplacées par cette logique de responsabilisation.",u:["https://www.cnil.fr/fr/definition/accountability"],s:"RGPD, art. 5 et 24"},
{id:"nu2-124",t:"num",q:"Quel document recense les traitements de données personnelles mis en œuvre par un organisme ?",o:["Le registre des activités de traitement","Le cahier des charges","Le plan de continuité d'activité","Le registre du commerce"],a:0,e:"Il décrit pour chaque traitement sa finalité, les données, les destinataires, la durée de conservation et les mesures de sécurité.",u:["https://www.cnil.fr/fr/RGPD-le-registre-des-activites-de-traitement"],s:"RGPD, art. 30"},
{id:"nu2-125",t:"num",q:"Quand une analyse d'impact relative à la protection des données (AIPD) est-elle obligatoire ?",o:["Pour tout traitement, sans exception","Uniquement pour les fichiers papier","Lorsque le traitement est susceptible d'engendrer un risque élevé pour les droits et libertés des personnes","Uniquement à la demande d'une personne concernée"],a:2,e:"Exemples : surveillance systématique à grande échelle, données sensibles à grande échelle, profilage aux effets importants.",u:["https://www.cnil.fr/fr/RGPD-analyse-impact-protection-des-donnees-aipd"],s:"RGPD, art. 35"},
{id:"nu2-126",t:"num",q:"Que signifie la « protection des données dès la conception » (privacy by design) ?",o:["Concevoir des sites au graphisme sobre","Confier la protection des données à un designer","Supprimer les données à la fin du projet","Intégrer la protection des données dès la conception d'un produit ou d'un service, et non après coup"],a:3,e:"Elle va de pair avec la protection par défaut : ne traiter que les données nécessaires.",s:"RGPD, art. 25"},
{id:"nu2-127",t:"num",q:"Quelle différence y a-t-il entre des données pseudonymisées et des données anonymisées ?",o:["Aucune","Les données pseudonymisées restent personnelles, car la réidentification reste possible avec des informations complémentaires ; les données anonymisées ne le sont plus","Les données anonymisées restent soumises au RGPD, pas les pseudonymisées","La pseudonymisation supprime définitivement les données"],a:1,e:"Une anonymisation réussie rend la réidentification impossible : le RGPD ne s'applique plus.",u:["https://fr.wikipedia.org/wiki/Pseudonymisation"],s:"Banque numérique"},
{id:"nu2-128",t:"num",q:"Combien de temps des données personnelles peuvent-elles être conservées selon le RGPD ?",o:["Pas plus longtemps que nécessaire au regard de la finalité du traitement","Indéfiniment","Dix ans dans tous les cas","Un an au maximum"],a:0,e:"Principe de limitation de la conservation : une durée doit être définie, éventuellement suivie d'un archivage.",s:"RGPD, art. 5"},
{id:"nu2-129",t:"num",q:"Quand une violation de données doit-elle aussi être communiquée aux personnes concernées ?",o:["Jamais, seule la CNIL est informée","Toujours, dans l'heure","Lorsqu'elle est susceptible d'engendrer un risque élevé pour leurs droits et libertés","Uniquement si elles le demandent"],a:2,e:"La notification à la CNIL intervient, elle, sous 72 heures si la violation présente un risque.",u:["https://www.cnil.fr/fr/services-en-ligne/notifier-une-violation-de-donnees-personnelles"],s:"RGPD, art. 34"},
{id:"nu2-130",t:"num",q:"Vers quels pays des données personnelles peuvent-elles être transférées depuis l'UE sans garantie supplémentaire ?",o:["Vers tout pays membre de l'ONU","Vers aucun pays hors de l'UE","Uniquement vers les États-Unis","Vers les pays reconnus par la Commission européenne comme offrant un niveau de protection adéquat"],a:3,e:"À défaut de décision d'adéquation, il faut des garanties appropriées (clauses contractuelles types, règles d'entreprise contraignantes…).",u:["https://www.cnil.fr/fr/la-protection-des-donnees-dans-le-monde"],s:"RGPD, art. 45"},
{id:"nu2-131",t:"num",q:"Comment s'appelle le cadre adopté en juillet 2023 pour les transferts de données personnelles de l'UE vers les États-Unis ?",o:["Safe Harbor","Privacy Shield","Data Privacy Framework","Cloud Act"],a:2,e:"Il succède au Safe Harbor, invalidé par la CJUE en 2015, et au Privacy Shield, invalidé en 2020 (arrêt Schrems II).",u:["https://fr.wikipedia.org/wiki/Data_Privacy_Framework"],s:"Banque numérique"},
{id:"nu2-132",t:"num",q:"Quel organe européen réunit les autorités nationales de protection des données et veille à l'application cohérente du RGPD ?",o:["Le Comité européen de la protection des données","Le Contrôleur européen de la protection des données","L'ENISA","Europol"],a:0,e:"Le Contrôleur européen surveille, lui, les institutions de l'UE ; l'ENISA est l'agence de l'UE pour la cybersécurité.",u:["https://fr.wikipedia.org/wiki/Comité_européen_de_la_protection_des_données"],s:"Banque numérique"},
{id:"nu2-133",t:"num",q:"Le RGPD s'applique-t-il à une entreprise établie hors de l'UE ?",o:["Non, jamais","Seulement si elle a des salariés en France","Seulement si elle est cotée en bourse","Oui, si elle propose des biens ou services à des personnes situées dans l'UE ou suit leur comportement"],a:3,e:"C'est le critère du ciblage : le lieu d'établissement n'est pas déterminant.",u:["https://fr.wikipedia.org/wiki/Règlement_général_sur_la_protection_des_données"],s:"RGPD, art. 3"},
{id:"nu2-134",t:"num",q:"Quel projet de fichier administratif, révélé par la presse en 1974, est à l'origine de la loi Informatique et libertés ?",o:["SIRENE","FICOBA","SAFARI","CYCLADES"],a:2,e:"Il prévoyait d'interconnecter les fichiers administratifs à partir du numéro de sécurité sociale ; il a conduit à la loi du 6 janvier 1978 et à la création de la CNIL.",u:["https://fr.wikipedia.org/wiki/Système_automatisé_pour_les_fichiers_administratifs_et_le_répertoire_des_individus"],s:"Banque numérique"},
{id:"nu2-135",t:"num",q:"Qu'est-ce qu'un cookie ?",o:["Un petit fichier déposé sur le terminal de l'internaute par un site, pour mémoriser des informations sur sa navigation","Un virus de messagerie","Un logiciel de traitement de texte","Une publicité affichée en pleine page"],a:0,e:"Un cookie « tiers » est déposé par un autre domaine que le site visité, souvent une régie publicitaire.",u:["https://www.cnil.fr/fr/definition/cookie"],s:"CNIL"},
{id:"nu2-136",t:"num",q:"Selon les règles appliquées par la CNIL, refuser les cookies non essentiels doit être :",o:["Impossible sur les sites commerciaux","Possible seulement par courrier","Réservé aux utilisateurs inscrits","Aussi simple que de les accepter"],a:3,e:"Un bouton « Tout refuser » doit être aussi accessible que « Tout accepter » ; la CNIL a sanctionné plusieurs grands sites à ce titre.",u:["https://www.cnil.fr/fr/cookies-et-autres-traceurs"],s:"CNIL"},
{id:"nu2-137",t:"num",q:"Quel texte européen est à l'origine des règles sur le dépôt de cookies ?",o:["La directive « vie privée et communications électroniques » (ePrivacy)","Le règlement MiCA","La directive NIS 2","Le règlement DMA"],a:0,e:"Elle est transposée à l'article 82 de la loi Informatique et libertés ; le RGPD définit les conditions du consentement.",u:["https://fr.wikipedia.org/wiki/Directive_vie_privée_et_communications_électroniques"],s:"Banque numérique"},
{id:"nu2-138",t:"num",q:"Quel est le rôle du délégué à la protection des données (DPO) ?",o:["Il est personnellement responsable de toute violation de données","Il délivre les autorisations de traitement à la place de la CNIL","Il informe et conseille l'organisme, contrôle le respect du RGPD et sert de point de contact avec la CNIL","Il gère le parc informatique"],a:2,e:"La responsabilité de la conformité reste celle du responsable de traitement.",u:["https://www.cnil.fr/fr/designation-dpo"],s:"RGPD, art. 39"},
{id:"nu2-139",t:"num",q:"Quelle loi a adapté la loi Informatique et libertés au RGPD en 2018 ?",o:["La loi pour une République numérique","La loi pour la confiance dans l'économie numérique","La loi relative à la protection des données personnelles du 20 juin 2018","La loi Godfrain"],a:2,e:"La loi Informatique et libertés a ensuite été réécrite par une ordonnance du 12 décembre 2018.",u:["https://www.cnil.fr/fr/le-cadre-national/la-loi-informatique-et-libertes"],s:"Banque numérique"},
{id:"nu2-140",t:"num",q:"Quelle est la référence du RGPD ?",o:["Directive 95/46/CE","Règlement (UE) 2016/679","Règlement (UE) 2022/2065","Directive (UE) 2016/680"],a:1,e:"Adopté le 27 avril 2016, il a abrogé la directive 95/46/CE. Le règlement 2022/2065 est le DSA ; la directive 2016/680 vise les traitements en matière pénale.",u:["https://www.cnil.fr/fr/reglement-europeen-protection-donnees"],s:"Banque numérique"},
{id:"nu2-141",t:"num",q:"Que permet la loi pour une République numérique de 2016 en matière de données personnelles après le décès ?",o:["Rien, les données sont supprimées automatiquement","Donner des directives sur la conservation, l'effacement et la communication de ses données après sa mort","Transmettre ses données à l'État","Vendre ses données à un tiers"],a:1,e:"Ces directives peuvent être générales ou particulières à un service ; elles sont modifiables à tout moment.",u:["https://fr.wikipedia.org/wiki/Loi_pour_une_République_numérique"],s:"Loi pour une République numérique"},

// --- Santé, bien-être et environnement ---
{id:"nu2-142",t:"num",q:"Comment placer son écran pour travailler longtemps dans de bonnes conditions ?",o:["Le haut de l'écran au-dessus du niveau des yeux","Le haut de l'écran à hauteur des yeux ou légèrement en dessous, à environ une longueur de bras","L'écran le plus près possible des yeux","L'écran face à une fenêtre lumineuse"],a:1,e:"L'INRS recommande aussi de placer l'écran perpendiculairement aux fenêtres pour éviter reflets et éblouissement.",u:["https://www.inrs.fr/risques/travail-ecran/ce-qu-il-faut-retenir.html"],s:"INRS"},
{id:"nu2-143",t:"num",q:"Que conseille la règle « 20-20-20 » pour limiter la fatigue visuelle devant un écran ?",o:["Toutes les 20 minutes, regarder au loin (environ 6 mètres) pendant 20 secondes","Travailler 20 heures par semaine au maximum","Régler la luminosité à 20 %","Se placer à 20 centimètres de l'écran"],a:0,e:"Ces pauses visuelles relâchent l'accommodation ; cligner des yeux limite aussi leur sécheresse.",s:"Banque numérique"},
{id:"nu2-144",t:"num",q:"Pourquoi est-il conseillé d'éviter les écrans avant de dormir ?",o:["Parce qu'ils consomment beaucoup d'électricité la nuit","Parce qu'ils provoquent des troubles musculosquelettiques","Parce que les mises à jour s'installent la nuit","Parce que leur lumière, riche en bleu, et la stimulation retardent l'endormissement"],a:3,e:"La lumière bleue perturbe la sécrétion de mélatonine, l'hormone du sommeil.",s:"Banque numérique"},
{id:"nu2-145",t:"num",q:"Que désigne l'infobésité ?",o:["Une maladie liée à la sédentarité devant l'écran","Une base de données de santé","La saturation d'un disque dur","L'excès d'informations et de sollicitations (courriels, notifications) qui nuit à la concentration"],a:3,e:"Bonnes pratiques : couper les notifications, traiter les courriels par plages, limiter les destinataires en copie.",u:["https://fr.wikipedia.org/wiki/Infobésité"],s:"Banque numérique"},
{id:"nu2-146",t:"num",q:"Dans les entreprises soumises à la négociation annuelle obligatoire, comment le droit à la déconnexion est-il organisé ?",o:["Par un arrêté préfectoral","Par une décision de l'inspection du travail","Par un accord négocié avec les syndicats ou, à défaut, par une charte élaborée par l'employeur","Par un règlement de la CNIL"],a:2,e:"Prévu par la loi Travail du 8 août 2016, applicable depuis le 1er janvier 2017.",u:["https://fr.wikipedia.org/wiki/Droit_à_la_déconnexion"],s:"Code du travail, art. L2242-17"},
{id:"nu2-147",t:"num",q:"Que désigne le sigle DEEE ?",o:["Les déchets d'équipements électriques et électroniques","La direction de l'économie et de l'emploi","Un format d'archive","Un diplôme d'expert en électronique"],a:0,e:"Ils doivent être collectés séparément : points de collecte, déchetteries ou reprise par le vendeur.",u:["https://fr.wikipedia.org/wiki/Déchets_d'équipements_électriques_et_électroniques"],s:"Banque numérique"},
{id:"nu2-148",t:"num",q:"Lors de l'achat d'un appareil électrique neuf, le vendeur doit-il reprendre l'ancien appareil ?",o:["Non, jamais","Oui, mais contre paiement","Seulement pour les téléphones","Oui, gratuitement, pour un appareil de même type : c'est la reprise « un pour un »"],a:3,e:"Les appareils sont ensuite dépollués et recyclés dans la filière DEEE.",u:["https://fr.wikipedia.org/wiki/Déchets_d'équipements_électriques_et_électroniques"],s:"Banque numérique"},
{id:"nu2-149",t:"num",q:"Quelle loi de 2020 a créé l'indice de réparabilité affiché sur certains équipements électriques et électroniques ?",o:["La loi REEN","La loi anti-gaspillage pour une économie circulaire (AGEC)","La loi pour une République numérique","La loi SREN"],a:1,e:"Loi du 10 février 2020 ; l'indice est apparu le 1er janvier 2021, notamment sur les smartphones et ordinateurs portables.",u:["https://fr.wikipedia.org/wiki/Indice_de_réparabilité","https://fr.wikipedia.org/wiki/Loi_relative_à_la_lutte_contre_le_gaspillage_et_à_l'économie_circulaire"],s:"Banque numérique"},
{id:"nu2-150",t:"num",q:"Quel est l'objet de la loi REEN du 15 novembre 2021 ?",o:["Réduire l'empreinte environnementale du numérique en France","Réguler les réseaux sociaux","Créer l'identité numérique","Encadrer l'intelligence artificielle"],a:0,e:"Elle vise notamment à sensibiliser aux impacts du numérique, à limiter le renouvellement des terminaux et à promouvoir des usages et des centres de données plus sobres.",s:"Banque numérique"},
{id:"nu2-151",t:"num",q:"Laquelle de ces mesures figure dans la loi REEN de 2021 ?",o:["L'interdiction des smartphones aux moins de 15 ans","La fermeture des centres de données","La création d'un référentiel général d'écoconception des services numériques","La gratuité de la fibre optique"],a:2,e:"Le référentiel (RGESN) fixe des critères pour concevoir des services numériques plus sobres.",s:"Banque numérique"},
{id:"nu2-152",t:"num",q:"Quelle loi a fait de l'obsolescence programmée un délit en France en 2015 ?",o:["La loi REEN","La loi relative à la transition énergétique pour la croissance verte","La loi AGEC","La loi Grenelle II"],a:1,e:"La loi REEN de 2021 a précisé que le délit couvre aussi l'obsolescence logicielle.",u:["https://fr.wikipedia.org/wiki/Obsolescence_programmée"],s:"Banque numérique"},
{id:"nu2-153",t:"num",q:"Laquelle de ces pratiques relève de la sobriété numérique ?",o:["Changer de smartphone chaque année","Regarder systématiquement les vidéos en très haute définition sur réseau mobile","Prolonger la durée de vie de ses équipements et les faire réparer","Envoyer des fichiers volumineux en pièce jointe à de nombreux destinataires"],a:2,e:"La fabrication des équipements pèse le plus dans l'empreinte environnementale du numérique.",u:["https://fr.wikipedia.org/wiki/Sobriété_numérique"],s:"Banque numérique"},
{id:"nu2-154",t:"num",q:"Qu'est-ce que l'écoconception d'un service numérique ?",o:["La prise en compte des impacts environnementaux dès la conception, pour limiter les ressources nécessaires (terminaux, réseaux, serveurs)","La conception d'un site sur le thème de l'écologie","La compensation carbone d'un site par la plantation d'arbres","La fermeture des services en ligne la nuit"],a:0,e:"Exemples : pages plus légères, fonctionnalités utiles seulement, compatibilité avec les appareils anciens.",u:["https://fr.wikipedia.org/wiki/Écoconception"],s:"Banque numérique"},

// --- Notions : IA, cloud, blockchain, open source, API ---
{id:"nu2-155",t:"num",q:"Qu'est-ce qu'un algorithme ?",o:["Une suite finie d'instructions permettant de résoudre un problème ou d'obtenir un résultat","Un composant électronique","Un langage de balisage","Un type de virus"],a:0,e:"Une recette de cuisine en est une image simple ; un programme met en œuvre des algorithmes.",u:["https://www.cnil.fr/fr/definition/algorithme"],s:"Banque numérique"},
{id:"nu2-156",t:"num",q:"Qu'est-ce que l'apprentissage automatique (machine learning) ?",o:["La formation des agents à l'informatique","Une méthode d'IA dans laquelle un système apprend à partir d'exemples (données) plutôt que d'être programmé règle par règle","L'installation automatique des mises à jour","La sauvegarde automatique des fichiers"],a:1,e:"L'apprentissage profond (deep learning) en est une branche fondée sur des réseaux de neurones à nombreuses couches.",u:["https://fr.wikipedia.org/wiki/Apprentissage_automatique"],s:"Banque numérique"},
{id:"nu2-157",t:"num",q:"Qu'est-ce qu'un grand modèle de langage (LLM) ?",o:["Un dictionnaire numérique officiel","Un service de traduction assuré par des humains","Un clavier multilingue","Un modèle d'IA entraîné sur de très grands volumes de textes pour comprendre et générer du langage"],a:3,e:"Il est au cœur des assistants conversationnels d'IA générative.",u:["https://fr.wikipedia.org/wiki/Grand_modèle_de_langage"],s:"Banque numérique"},
{id:"nu2-158",t:"num",q:"Qu'appelle-t-on une « hallucination » d'une IA générative ?",o:["Une image très colorée","Une réponse fausse ou inventée, présentée de façon plausible","Une panne du serveur","Un piratage de l'IA"],a:1,e:"D'où la nécessité de vérifier les sources et les faits avancés par l'IA.",u:["https://fr.wikipedia.org/wiki/Hallucination_(intelligence_artificielle)"],s:"Banque numérique"},
{id:"nu2-159",t:"num",q:"Qu'est-ce qu'Albert ?",o:["Le moteur de recherche officiel de l'État","La messagerie instantanée des agents","Le cloud du ministère des Finances","Une IA générative développée par l'État (DINUM) pour aider les agents publics"],a:3,e:"Elle a d'abord été utilisée dans le réseau France Services pour aider les conseillers à répondre aux usagers.",s:"Banque numérique"},
{id:"nu2-160",t:"num",q:"Qu'est-ce qu'un biais algorithmique ?",o:["Un résultat systématiquement faussé ou discriminatoire, souvent dû aux données d'apprentissage","Une erreur de frappe dans le code","Un ralentissement du processeur","Un algorithme de compression"],a:0,e:"Un système entraîné sur des données déséquilibrées reproduit ces déséquilibres.",u:["https://fr.wikipedia.org/wiki/Biais_algorithmique"],s:"Banque numérique"},
{id:"nu2-161",t:"num",q:"Qu'est-ce qu'un objet connecté ?",o:["Un logiciel de visioconférence","Un câble USB","Un site web marchand","Un objet physique muni de capteurs, relié à Internet pour échanger des données (montre, thermostat…)"],a:3,e:"L'ensemble forme l'Internet des objets (IoT).",u:["https://fr.wikipedia.org/wiki/Internet_des_objets"],s:"Banque numérique"},
{id:"nu2-162",t:"num",q:"Qu'est-ce qu'un cloud hybride ?",o:["Un cloud alimenté à l'énergie solaire","Un cloud réservé aux véhicules connectés","Un service sans aucun serveur","La combinaison d'un cloud privé (ou d'une infrastructure interne) et d'un cloud public"],a:3,e:"Cloud privé : dédié à une organisation ; cloud public : ressources mutualisées d'un fournisseur.",u:["https://fr.wikipedia.org/wiki/Cloud_computing"],s:"Banque numérique"},
{id:"nu2-163",t:"num",q:"Dans le modèle IaaS (infrastructure en tant que service), que fournit le prestataire ?",o:["Un logiciel prêt à l'emploi, utilisable dans le navigateur","Une formation des utilisateurs","Des ressources d'infrastructure (serveurs, stockage, réseau) ; le client gère systèmes et applications","Un ordinateur portable"],a:2,e:"Le logiciel prêt à l'emploi correspond au SaaS ; le PaaS fournit une plateforme de développement.",u:["https://fr.wikipedia.org/wiki/Cloud_computing"],s:"Banque numérique"},
{id:"nu2-164",t:"num",q:"Quelle doctrine, fixée par une circulaire du Premier ministre de 2021, fait du cloud l'hébergement par défaut des projets numériques de l'État ?",o:["« Cloud au centre »","« Dites-le-nous une fois »","« Zéro papier »","« Tech for Good »"],a:0,e:"Actualisée en 2023, elle impose une offre qualifiée SecNumCloud pour les données les plus sensibles.",s:"Banque numérique"},
{id:"nu2-165",t:"num",q:"Que désigne le « minage » d'une cryptomonnaie comme le bitcoin ?",o:["L'extraction de métaux rares pour fabriquer les ordinateurs","Le vol de portefeuilles numériques","La conversion de cryptoactifs en euros","La validation des transactions et la création de nouveaux blocs par calcul informatique, rémunérées en cryptoactifs"],a:3,e:"Ce mécanisme (preuve de travail) consomme beaucoup d'électricité. Le bitcoin, lancé en 2009, est la première cryptomonnaie.",u:["https://fr.wikipedia.org/wiki/Bitcoin"],s:"Banque numérique"},
{id:"nu2-166",t:"num",q:"Quel règlement européen encadre les émetteurs de cryptoactifs et les prestataires de services sur cryptoactifs ?",o:["MiCA","DSA","DORA","eIDAS"],a:0,e:"Markets in Crypto-Assets, pleinement applicable depuis le 30 décembre 2024. DORA porte sur la résilience opérationnelle numérique du secteur financier.",s:"Banque numérique"},
{id:"nu2-167",t:"num",q:"Qu'est-ce qu'un NFT (jeton non fongible) ?",o:["Une monnaie interchangeable comme l'euro","Un format de fichier vidéo","Un logiciel antivirus","Un jeton numérique unique, inscrit sur une blockchain et associé à un actif (souvent numérique)"],a:3,e:"« Non fongible » : il n'est pas interchangeable avec un autre, contrairement à une unité de monnaie.",u:["https://fr.wikipedia.org/wiki/Jeton_non_fongible"],s:"Banque numérique"},
{id:"nu2-168",t:"num",q:"Que vise le projet d'euro numérique porté par la BCE ?",o:["Remplacer les billets et les pièces","Créer une cryptomonnaie privée","Offrir au public une monnaie de banque centrale sous forme électronique, en complément des espèces","Supprimer les comptes bancaires"],a:2,e:"Ce ne serait pas une cryptomonnaie, mais une monnaie émise par la banque centrale ; en 2026, la BCE vise une première émission potentielle en 2029, si le règlement européen est adopté, après un projet pilote en 2027.",u:["https://www.ecb.europa.eu/euro/digital_euro/html/index.fr.html","https://fr.wikipedia.org/wiki/Euro_num%C3%A9rique"],s:"Banque numérique",act:1},
{id:"nu2-169",t:"num",q:"Lequel de ces logiciels est un logiciel libre ?",o:["Microsoft Word","Adobe Photoshop","LibreOffice","Windows 11"],a:2,e:"Comme Firefox, Thunderbird ou VLC ; les autres sont des logiciels propriétaires.",u:["https://fr.wikipedia.org/wiki/LibreOffice","https://fr.wikipedia.org/wiki/Logiciel_libre"],s:"Banque numérique"},
{id:"nu2-170",t:"num",q:"Qu'est-ce que le SILL ?",o:["Le socle interministériel de logiciels libres, liste de logiciels libres recommandés aux administrations","Un service de sauvegarde en ligne","Un système d'information sur les loyers","Un indice de sécurité des logiciels"],a:0,e:"Il est tenu par la DINUM avec des agents publics utilisateurs.",u:["https://fr.wikipedia.org/wiki/Socle_interministériel_de_logiciels_libres"],s:"Banque numérique"},
{id:"nu2-171",t:"num",q:"Qu'est-ce qu'une API (interface de programmation) ?",o:["Un écran tactile","Une interface qui permet à des logiciels d'échanger automatiquement des données ou des services","Une adresse IP privée","Un antivirus en ligne"],a:1,e:"Les administrations s'en servent pour échanger des données sans les redemander aux usagers.",u:["https://fr.wikipedia.org/wiki/Interface_de_programmation"],s:"Banque numérique"},
{id:"nu2-172",t:"num",q:"À quoi sert l'API Particulier proposée aux administrations ?",o:["À permettre aux usagers de payer leurs factures en ligne","À publier les données personnelles en open data","À créer un compte FranceConnect","À permettre à une administration d'obtenir directement certaines données d'un usager (quotient familial, statut étudiant…) sans lui réclamer de justificatifs"],a:3,e:"C'est une mise en œuvre concrète du principe « Dites-le-nous une fois ».",u:["https://www.data.gouv.fr/dataservices/api-particulier"],s:"Banque numérique"},
{id:"nu2-173",t:"num",q:"Que désigne la « souveraineté numérique » ?",o:["La capacité d'un État ou de l'UE à maîtriser ses données, ses infrastructures et ses technologies sans dépendre de puissances étrangères","Le droit de chaque internaute à un accès gratuit à Internet","Le monopole de l'État sur les réseaux","L'interdiction des logiciels étrangers"],a:0,e:"Elle justifie par exemple le recours à des clouds qualifiés SecNumCloud ou à des outils libres.",u:["https://fr.wikipedia.org/wiki/Souveraineté_numérique"],s:"Banque numérique"},
{id:"nu2-174",t:"num",q:"Pourquoi le Cloud Act américain de 2018 préoccupe-t-il les Européens ?",o:["Il interdit le cloud en Europe","Il permet aux autorités américaines d'exiger d'un fournisseur américain des données qu'il stocke, même hors des États-Unis","Il impose une taxe sur les données","Il oblige à héberger les données aux États-Unis"],a:1,e:"D'où l'exigence d'immunité aux lois extra-européennes pour les données sensibles de l'État.",u:["https://fr.wikipedia.org/wiki/CLOUD_Act"],s:"Banque numérique"},

// --- Administration numérique ---
{id:"nu2-175",t:"num",q:"Quelle direction interministérielle, créée en 2019, pilote la transformation numérique de l'État ?",o:["La DGAFP","La DINUM","La DITP","La DAE"],a:1,e:"Direction interministérielle du numérique ; la DITP s'occupe de la transformation publique, la DGAFP de la fonction publique, la DAE des achats de l'État.",u:["https://fr.wikipedia.org/wiki/Direction_interministérielle_du_numérique"],s:"Banque numérique"},
{id:"nu2-176",t:"num",q:"Quel service de la DINUM est chargé de la politique d'ouverture et de circulation des données publiques ?",o:["Etalab","Pix","Tchap","PHAROS"],a:0,e:"Il administre notamment data.gouv.fr et la Licence ouverte.",u:["https://fr.wikipedia.org/wiki/Etalab"],s:"Banque numérique"},
{id:"nu2-177",t:"num",q:"Qu'est-ce que FranceConnect+ ?",o:["Une version payante de FranceConnect","Un réseau social de l'administration","Une version renforcée de FranceConnect, au niveau de sécurité plus élevé, pour les démarches sensibles","L'application mobile de impots.gouv.fr"],a:2,e:"Elle s'appuie sur des identités numériques de niveau de garantie supérieur, comme France Identité.",u:["https://fr.wikipedia.org/wiki/FranceConnect"],s:"Banque numérique"},
{id:"nu2-178",t:"num",q:"Que permet l'application France Identité ?",o:["De prouver son identité en ligne grâce à la carte nationale d'identité au format carte bancaire","De déclarer ses revenus","De prendre rendez-vous chez le médecin","De voter par Internet aux élections nationales"],a:0,e:"Elle lit la puce de la carte d'identité ; la puce contient l'état civil, la photo et les empreintes digitales.",u:["https://fr.wikipedia.org/wiki/France_Identité"],s:"Banque numérique"},
{id:"nu2-179",t:"num",q:"Que permet le droit de saisine de l'administration par voie électronique (SVE) ?",o:["De saisir le juge administratif par simple courriel","De recevoir son avis d'impôt par SMS","D'obtenir une réponse dans l'heure","D'adresser à l'administration une demande, une déclaration ou une information par voie électronique, comme on le ferait par courrier"],a:3,e:"Ce droit figure dans le code des relations entre le public et l'administration (art. L112-8 et suivants).",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F33312"],s:"CRPA"},
{id:"nu2-180",t:"num",q:"Lorsqu'un usager saisit une administration par voie électronique, celle-ci doit :",o:["Lui demander de confirmer par courrier recommandé","Lui facturer des frais de dossier","Ignorer la demande si elle n'est pas signée à la main","Lui adresser un accusé de réception électronique"],a:3,e:"L'accusé de réception électronique mentionne la date de réception de la demande.",u:["https://www.service-public.gouv.fr/particuliers/vosdroits/F33312"],s:"CRPA, art. L112-11"},
{id:"nu2-181",t:"num",q:"Que désigne le RGAA ?",o:["Le règlement général sur l'archivage administratif","Le référentiel général d'amélioration de l'accessibilité, qui fixe les critères d'accessibilité numérique pour les personnes handicapées","Le répertoire des agents de l'administration","Le registre général des adresses"],a:1,e:"Il s'applique aux sites et applications des administrations et de certaines entreprises.",u:["https://fr.wikipedia.org/wiki/Référentiel_général_d'amélioration_de_l'accessibilité","https://accessibilite.numerique.gouv.fr/"],s:"Banque numérique"},
{id:"nu2-182",t:"num",q:"Que doit afficher, dès sa page d'accueil, un site soumis à l'obligation d'accessibilité numérique ?",o:["Le nom de son hébergeur uniquement","Le nombre de visiteurs du mois","Le coût de développement du site","Une mention de son niveau de conformité : totalement, partiellement ou non conforme"],a:3,e:"Une déclaration d'accessibilité détaille les résultats et les voies de recours.",u:["https://accessibilite.numerique.gouv.fr/"],s:"Banque numérique"},
{id:"nu2-183",t:"num",q:"Quelle est la mission des conseillers numériques déployés depuis 2021 ?",o:["Contrôler la sécurité des sites publics","Réparer les ordinateurs des administrations","Vendre des abonnements Internet","Accompagner les usagers dans l'appropriation des outils et usages numériques du quotidien"],a:3,e:"Ce dispositif, financé par l'État, contribue à la lutte contre l'illectronisme.",s:"Banque numérique"},
{id:"nu2-184",t:"num",q:"Quel est le rôle des espaces France Services ?",o:["Accompagner les usagers, près de chez eux, dans leurs démarches auprès de plusieurs administrations et organismes (impôts, CAF, retraite…)","Vendre des services numériques aux entreprises","Délivrer directement les passeports","Juger les litiges avec l'administration"],a:0,e:"La DGFiP fait partie des partenaires du réseau ; les agents y aident aussi aux démarches en ligne.",u:["https://fr.wikipedia.org/wiki/France_Services"],s:"Banque numérique"},
{id:"nu2-185",t:"num",q:"Selon le Conseil d'État (2022), une administration peut-elle rendre obligatoire le recours à un téléservice ?",o:["Non, jamais","Oui, sans aucune condition","Oui, à condition de garantir l'accès au service, notamment par un accompagnement ou une solution de substitution pour les usagers qui ne peuvent l'utiliser","Seulement pour les entreprises"],a:2,e:"Le Défenseur des droits rappelle de même qu'aucun usager ne doit être privé d'accès au service public faute de maîtrise du numérique.",s:"Conseil d'État, 3 juin 2022"},
{id:"nu2-186",t:"num",q:"Selon la loi pour une République numérique de 2016, le code source d'un logiciel développé par une administration est :",o:["Un document administratif communicable","Un secret protégé par principe","La propriété exclusive du développeur","Une donnée personnelle"],a:0,e:"La loi a ajouté les codes sources à la liste des documents administratifs (CRPA, art. L300-2). Elle consacre un avis de la CADA de 2015, à la suite duquel la DGFiP avait publié en avril 2016 le code source du calculateur de l'impôt sur le revenu.",u:["https://fr.wikipedia.org/wiki/Loi_pour_une_République_numérique"],s:"Banque numérique"},
{id:"nu2-187",t:"num",q:"Lorsqu'une décision individuelle est prise sur le fondement d'un traitement algorithmique, l'administration doit :",o:["Garder l'algorithme secret","Faire valider chaque décision par la CNIL","Faire signer la décision par un ministre","En informer l'intéressé par une mention explicite et lui communiquer, à sa demande, les règles et les principales caractéristiques du traitement"],a:3,e:"Obligation issue de la loi pour une République numérique de 2016.",s:"CRPA, art. L311-3-1"},
{id:"nu2-188",t:"num",q:"Quels sont les trois niveaux de garantie des moyens d'identification électronique définis par le règlement eIDAS ?",o:["Bas, moyen, haut","Simple, avancé, qualifié","Public, privé, mixte","Faible, substantiel, élevé"],a:3,e:"« Simple, avancée, qualifiée » désigne en revanche les niveaux de signature électronique.",u:["https://fr.wikipedia.org/wiki/EIDAS"],s:"Règlement eIDAS"},
{id:"nu2-189",t:"num",q:"Selon le règlement eIDAS, quelle signature électronique a un effet juridique équivalent à celui d'une signature manuscrite dans toute l'UE ?",o:["La signature simple","La signature avancée","La signature qualifiée","La signature scannée"],a:2,e:"Elle repose sur un certificat qualifié et un dispositif de création de signature qualifié.",u:["https://fr.wikipedia.org/wiki/Signature_électronique"],s:"Règlement eIDAS"},
{id:"nu2-190",t:"num",q:"Que prévoit le règlement eIDAS 2, adopté en 2024 ?",o:["La suppression des cartes d'identité","Un portefeuille européen d'identité numérique que chaque État membre doit proposer à ses citoyens","Une monnaie numérique européenne","L'interdiction de la signature électronique"],a:1,e:"Il permettra de stocker et présenter des attestations (identité, diplômes, permis…).",u:["https://fr.wikipedia.org/wiki/EIDAS"],s:"Banque numérique"},
{id:"nu2-191",t:"num",q:"Une lettre recommandée électronique qualifiée a-t-elle la même valeur qu'une lettre recommandée papier ?",o:["Oui, elle lui est équivalente","Non, elle n'a aucune valeur juridique","Seulement entre administrations","Seulement si elle est imprimée et signée"],a:0,e:"Le code des postes et des communications électroniques l'assimile à la lettre recommandée papier.",s:"Banque numérique"},
{id:"nu2-192",t:"num",q:"Qu'est-ce que Chorus Pro ?",o:["La plateforme de facturation électronique pour les factures adressées aux entités publiques","Le réseau social des agents de l'État","Le logiciel de paie des fonctionnaires","Un service de visioconférence"],a:0,e:"Depuis le 1er janvier 2020, tous les fournisseurs du secteur public, y compris les microentreprises, doivent y déposer leurs factures.",s:"Banque numérique"},

// --- DGFiP et numérique ---
{id:"nu2-193",t:"num",q:"En quoi consiste la déclaration automatique des revenus ?",o:["L'administration déclare à la place de tous les contribuables, sans possibilité de correction","Les contribuables dont la déclaration préremplie est exacte et complète n'ont aucune démarche à faire","L'employeur envoie lui-même la déclaration","Les revenus sont déclarés chaque mois"],a:1,e:"Mise en place en 2020 ; les foyers concernés vérifient les informations et peuvent toujours corriger ou compléter.",u:["https://www.impots.gouv.fr/particulier/questions/quest-ce-que-la-declaration-automatique-suis-je-eligible"],s:"impots.gouv.fr"},
{id:"nu2-194",t:"num",q:"La déclaration de revenus en ligne est-elle obligatoire ?",o:["Non, elle reste toujours facultative","Oui, sans aucune exception","Oui, si la résidence principale est équipée d'un accès à Internet, sauf si l'usager indique ne pas être en mesure de déclarer en ligne","Uniquement pour les revenus supérieurs à 100 000 €"],a:2,e:"L'obligation est généralisée depuis 2019 ; la déclaration papier reste possible pour les usagers qui ne peuvent pas déclarer en ligne.",s:"Banque numérique"},
{id:"nu2-195",t:"num",q:"Dans l'espace particulier de impots.gouv.fr, quelle rubrique permet notamment de moduler son taux de prélèvement à la source ?",o:["« Gérer mes biens immobiliers »","« Gérer mon prélèvement à la source »","« Mes documents »","« Payer en ligne »"],a:1,e:"On peut aussi y choisir le taux individualisé ou non personnalisé et gérer ses acomptes.",u:["https://fr.wikipedia.org/wiki/Prélèvement_à_la_source"],s:"impots.gouv.fr"},
{id:"nu2-196",t:"num",q:"Par quel service en ligne de impots.gouv.fr les propriétaires ont-ils dû, en 2023, déclarer l'occupation de leurs logements ?",o:["« Gérer mon prélèvement à la source »","« Payer en ligne »","« Mes avis »","« Gérer mes biens immobiliers »"],a:3,e:"Depuis, une nouvelle déclaration n'est exigée qu'en cas de changement de situation.",u:["https://www.impots.gouv.fr/particulier/je-declare-loccupant-de-mon-bien-immobilier"],s:"impots.gouv.fr"},
{id:"nu2-197",t:"num",q:"Avec le prélèvement à la source, qui prélève l'impôt sur le revenu dû sur un salaire ?",o:["Le salarié lui-même, par virement mensuel","La banque du salarié","L'employeur, qui le retient sur le salaire et le reverse à la DGFiP","La caisse de retraite"],a:2,e:"La DGFiP transmet le taux à l'employeur, qui l'applique et déclare les montants par la DSN.",u:["https://fr.wikipedia.org/wiki/Prélèvement_à_la_source"],s:"Banque numérique"},
{id:"nu2-198",t:"num",q:"Par quelle déclaration dématérialisée l'employeur transmet-il chaque mois les données de paie, dont le prélèvement à la source ?",o:["La déclaration sociale nominative (DSN)","La liasse fiscale","La déclaration 2042","Un formulaire Cerfa papier"],a:0,e:"Une seule transmission mensuelle remplace de nombreuses déclarations sociales.",u:["https://fr.wikipedia.org/wiki/Déclaration_sociale_nominative"],s:"Banque numérique"},
{id:"nu2-199",t:"num",q:"Au-delà de quel montant un impôt doit-il obligatoirement être payé de façon dématérialisée (prélèvement ou paiement en ligne) ?",o:["100 €","300 €","1 000 €","10 000 €"],a:1,e:"Seuil applicable depuis 2019 ; au-dessous, d'autres moyens restent possibles.",s:"CGI, art. 1681 sexies"},
{id:"nu2-200",t:"num",q:"Dans la réforme de la facturation électronique, comment appelle-t-on la transmission à l'administration des données des opérations non couvertes par une facture électronique entre entreprises (ventes aux particuliers, opérations internationales) ?",o:["Le e-invoicing","Le e-reporting","Le e-paiement","Le e-contact"],a:1,e:"Le e-invoicing désigne l'échange des factures électroniques elles-mêmes entre entreprises.",u:["https://www.impots.gouv.fr/professionnel/je-decouvre-la-facturation-electronique"],s:"impots.gouv.fr",act:1},
{id:"nu2-201",t:"num",q:"Par quel intermédiaire les entreprises émettent-elles et reçoivent-elles leurs factures électroniques dans le cadre de la réforme ?",o:["Par simple courriel avec un PDF joint","Par la messagerie sécurisée de impots.gouv.fr","Par courrier recommandé","Par une plateforme agréée par l'administration fiscale"],a:3,e:"Les plateformes agréées (anciennement « PDP ») transmettent aussi les données utiles à l'administration ; l'entreprise choisit librement la sienne.",u:["https://www.impots.gouv.fr/facturation-electronique-et-plateformes-agreees"],s:"impots.gouv.fr",act:1},
{id:"nu2-202",t:"num",q:"Quel format de facture électronique associe un PDF lisible par l'humain et des données structurées en XML ?",o:["UBL","CII","Factur-X","PNG"],a:2,e:"Factur-X, UBL et CII sont les trois formats du socle de la réforme ; UBL et CII sont des formats purement structurés.",u:["https://www.impots.gouv.fr/professionnel/je-decouvre-la-facturation-electronique"],s:"impots.gouv.fr"},
{id:"nu2-203",t:"num",q:"Une facture PDF « simple » envoyée par courriel entre deux entreprises répond-elle à l'obligation de facturation électronique ?",o:["Oui, tout PDF est une facture électronique","Non : il faut une facture au format structuré ou mixte, transmise par une plateforme agréée","Oui, si le PDF est signé","Oui, si le courriel est chiffré"],a:1,e:"Le PDF seul n'est pas exploitable automatiquement par l'administration.",u:["https://www.impots.gouv.fr/professionnel/je-decouvre-la-facturation-electronique"],s:"impots.gouv.fr",act:1},
{id:"nu2-204",t:"num",q:"Combien de chiffres compte le numéro fiscal d'un particulier, indiqué sur ses avis d'impôt ?",o:["9","11","13","15"],a:2,e:"Il sert d'identifiant pour l'espace particulier ; à ne pas confondre avec le numéro de sécurité sociale (13 caractères et une clé de 2 chiffres).",s:"impots.gouv.fr"},
{id:"nu2-205",t:"num",q:"Quelle base de données publiée en open data par la DGFiP recense les transactions immobilières ?",o:["SIRENE","DVF (Demandes de valeurs foncières)","FICOBA","Base adresse nationale"],a:1,e:"Elle permet de connaître les prix de vente des biens ; SIRENE est le répertoire des entreprises tenu par l'Insee.",u:["https://www.data.gouv.fr/datasets/demandes-de-valeurs-foncieres"],s:"data.gouv.fr"},
{id:"nu2-206",t:"num",q:"Quelle méthode la DGFiP utilise-t-elle pour mieux cibler les contrôles fiscaux ?",o:["Le tirage au sort intégral","Les dénonciations anonymes uniquement","Le contrôle systématique de tous les contribuables","L'exploration de données (data mining) et l'intelligence artificielle"],a:3,e:"Le ciblage par analyse de données s'est développé depuis 2014 ; il croise de nombreuses sources d'information.",s:"Banque numérique"},
{id:"nu2-207",t:"num",q:"Quel projet de la DGFiP exploite l'IA et les prises de vue aériennes pour détecter des constructions non déclarées, comme les piscines ?",o:["Foncier innovant","Patrim","Gérer mes biens immobiliers","DVF"],a:0,e:"Les images publiques de l'IGN sont analysées puis rapprochées des données cadastrales.",s:"Banque numérique"},
{id:"nu2-208",t:"num",q:"Qu'est-ce que FICOBA, géré par la DGFiP ?",o:["Le fichier des contribuables résidant à l'étranger","La base des factures électroniques","Le fichier national des comptes bancaires et assimilés","Le fichier des cartes grises"],a:2,e:"Il recense les comptes ouverts en France (sans les soldes ni les opérations).",u:["https://fr.wikipedia.org/wiki/FICOBA"],s:"Banque numérique"},
{id:"nu2-209",t:"num",q:"Depuis octobre 2014, quelle obligation s'applique à toutes les entreprises soumises à la TVA, quel que soit leur chiffre d'affaires ?",o:["Télédéclarer et télépayer la TVA","Payer la TVA en espèces","Déclarer la TVA une fois tous les cinq ans","Faire certifier la TVA par la CNIL"],a:0,e:"Les démarches se font depuis l'espace professionnel de impots.gouv.fr.",s:"Banque numérique"},
{id:"nu2-210",t:"num",q:"Quel texte a autorisé, à titre expérimental, l'administration fiscale et la douane à collecter les contenus publiés librement sur les plateformes en ligne pour détecter la fraude ?",o:["Le règlement eIDAS","La loi de finances pour 2020","La loi Informatique et libertés de 1978","Une simple instruction interne"],a:1,e:"La CNIL avait rendu un avis demandant des garanties sur ce dispositif inédit.",u:["https://www.cnil.fr/fr/projet-de-loi-de-finances-2020-publication-de-lavis-de-la-cnil"],s:"Banque numérique"},

// --- Réglementation européenne et française ---
{id:"nu2-211",t:"num",q:"Quel est l'objet principal du règlement européen sur les services numériques (DSA) ?",o:["Fixer le prix des abonnements Internet","Responsabiliser les plateformes en ligne face aux contenus illicites, à la désinformation et aux risques pour les utilisateurs","Créer une monnaie numérique","Réguler les cryptoactifs"],a:1,e:"Applicable à toutes les plateformes depuis le 17 février 2024 ; les très grandes plateformes ont des obligations renforcées.",u:["https://fr.wikipedia.org/wiki/Règlement_sur_les_services_numériques"],s:"Banque numérique"},
{id:"nu2-212",t:"num",q:"Quel est l'objet du règlement sur les marchés numériques (DMA) ?",o:["Protéger les données de santé","Encadrer la vente de matériel informatique","Fixer les tarifs des opérateurs mobiles","Garantir une concurrence loyale en imposant des obligations aux grandes plateformes « contrôleurs d'accès »"],a:3,e:"Exemples d'obligations : permettre de désinstaller les applications préinstallées, ne pas favoriser ses propres services.",u:["https://fr.wikipedia.org/wiki/Règlement_sur_les_marchés_numériques"],s:"Banque numérique"},
{id:"nu2-213",t:"num",q:"À partir de combien d'utilisateurs actifs mensuels dans l'UE une plateforme est-elle qualifiée de « très grande plateforme en ligne » par le DSA ?",o:["1 million","10 millions","45 millions","100 millions"],a:2,e:"45 millions représentent environ 10 % de la population de l'UE.",u:["https://fr.wikipedia.org/wiki/Règlement_sur_les_services_numériques"],s:"Banque numérique"},
{id:"nu2-214",t:"num",q:"Quelle autorité française est le coordinateur pour les services numériques chargé de l'application du DSA ?",o:["La CNIL","L'Arcep","L'Arcom","L'ANSSI"],a:2,e:"Désignée par la loi SREN de 2024 ; l'Arcom est née en 2022 de la fusion du CSA et de la Hadopi.",u:["https://fr.wikipedia.org/wiki/Autorité_de_régulation_de_la_communication_audiovisuelle_et_numérique"],s:"Banque numérique"},
{id:"nu2-215",t:"num",q:"Quel est l'objet de la loi SREN du 21 mai 2024 ?",o:["Sécuriser et réguler l'espace numérique : protection des mineurs, lutte contre les arnaques, adaptation au DSA et au DMA","Réformer la fiscalité du numérique","Créer la CNIL","Réduire l'empreinte environnementale du numérique"],a:0,e:"Elle prévoit notamment un filtre de cybersécurité anti-arnaque et renforce les pouvoirs de l'Arcom.",s:"Banque numérique"},
{id:"nu2-216",t:"num",q:"Que prévoit notamment la loi SREN de 2024 pour protéger les mineurs ?",o:["L'interdiction d'Internet aux moins de 18 ans","La fermeture des réseaux sociaux le soir","L'obligation pour les sites pornographiques de vérifier l'âge de leurs utilisateurs selon un référentiel de l'Arcom","Le contrôle parental obligatoire sur les ordinateurs publics"],a:2,e:"Une simple déclaration de majorité ne suffit pas ; l'Arcom peut faire bloquer les sites récalcitrants.",s:"Banque numérique"},
{id:"nu2-217",t:"num",q:"Quand le règlement européen sur l'intelligence artificielle (AI Act) est-il entré en vigueur ?",o:["Le 25 mai 2018","Le 1er août 2024","Le 17 février 2024","Le 1er janvier 2026"],a:1,e:"Ses obligations s'appliquent par étapes : pratiques interdites dès le 2 février 2025, modèles d'IA à usage général dès le 2 août 2025…",u:["https://fr.wikipedia.org/wiki/Règlement_sur_l'intelligence_artificielle"],s:"Banque numérique"},
{id:"nu2-218",t:"num",q:"Laquelle de ces pratiques est interdite par le règlement européen sur l'IA ?",o:["Le filtrage des courriels indésirables","La traduction automatique","La notation sociale des personnes","La recommandation de films"],a:2,e:"La notation sociale relève du risque inacceptable ; les filtres antispam, du risque minimal.",u:["https://fr.wikipedia.org/wiki/Règlement_sur_l'intelligence_artificielle"],s:"Banque numérique"},
{id:"nu2-219",t:"num",q:"Que prévoit le règlement européen sur l'IA pour les hypertrucages (deepfakes) ?",o:["Leur interdiction totale","Leur réservation aux médias publics","Leur autorisation sans condition","L'obligation d'indiquer que le contenu a été généré ou manipulé artificiellement"],a:3,e:"C'est une obligation de transparence, qui vise aussi les échanges avec un agent conversationnel.",u:["https://fr.wikipedia.org/wiki/Règlement_sur_l'intelligence_artificielle"],s:"AI Act, art. 50"},
{id:"nu2-220",t:"num",q:"Laquelle de ces mesures est issue de la loi pour une République numérique de 2016 ?",o:["La création de la CNIL","Le maintien temporaire de la connexion à Internet pour les foyers en difficulté de paiement","Le prélèvement à la source","La création de l'Arcom"],a:1,e:"La loi a aussi posé l'ouverture des données publiques par défaut et le principe de neutralité du net en droit français.",u:["https://fr.wikipedia.org/wiki/Loi_pour_une_République_numérique"],s:"Banque numérique"},
{id:"nu2-221",t:"num",q:"Que signifie le principe de neutralité du net ?",o:["Les sites ne doivent pas publier d'opinions politiques","L'accès à Internet doit être gratuit","Les opérateurs doivent traiter de façon égale tous les flux de données, sans discrimination selon leur source, leur destination ou leur contenu","Les moteurs de recherche doivent classer les sites par ordre alphabétique"],a:2,e:"Il est garanti par un règlement européen de 2015 ; l'Arcep veille à son respect en France.",u:["https://fr.wikipedia.org/wiki/Neutralité_du_réseau"],s:"Banque numérique"},
{id:"nu2-222",t:"num",q:"Quelle loi de 2004 définit notamment le régime de responsabilité des hébergeurs de contenus en ligne ?",o:["La loi pour la confiance dans l'économie numérique (LCEN)","La loi Informatique et libertés","La loi Hadopi","La loi SREN"],a:0,e:"Loi du 21 juin 2004 ; elle a aussi encadré le commerce électronique.",u:["https://fr.wikipedia.org/wiki/Loi_pour_la_confiance_dans_l'économie_numérique"],s:"Banque numérique"},
{id:"nu2-223",t:"num",q:"Un hébergeur est-il responsable des contenus illicites mis en ligne par ses utilisateurs ?",o:["Oui, toujours","Non, jamais","Seulement s'il en a eu connaissance et n'a pas agi promptement pour les retirer","Seulement si le contenu est en français"],a:2,e:"Il n'a pas d'obligation générale de surveillance ; ce régime est repris par le DSA.",u:["https://fr.wikipedia.org/wiki/Loi_pour_la_confiance_dans_l'économie_numérique"],s:"Banque numérique"},
{id:"nu2-224",t:"num",q:"Quel est l'objet de la directive européenne NIS 2 ?",o:["Encadrer les cryptoactifs","Renforcer la cybersécurité des entités essentielles et importantes dans de nombreux secteurs","Protéger le droit d'auteur en ligne","Organiser le vote électronique"],a:1,e:"Elle élargit fortement le champ de la première directive NIS de 2016, y compris à des administrations.",u:["https://fr.wikipedia.org/wiki/Directive_NIS_2"],s:"Banque numérique"},
{id:"nu2-225",t:"num",q:"Quel règlement européen impose des exigences de cybersécurité aux produits comportant des éléments numériques (objets connectés, logiciels) ?",o:["Le DSA","Le DMA","MiCA","Le Cyber Resilience Act (règlement sur la cyberrésilience)"],a:3,e:"Les fabricants devront notamment fournir des mises à jour de sécurité pendant la durée d'utilisation prévue.",u:["https://fr.wikipedia.org/wiki/Cyber_Resilience_Act"],s:"Banque numérique"},
{id:"nu2-226",t:"num",q:"Quel règlement européen, applicable depuis septembre 2025, organise l'accès et le partage des données générées par les objets connectés ?",o:["Le RGPD","Le DSA","Le Data Act (règlement sur les données)","Le règlement eIDAS"],a:2,e:"Il permet notamment à l'utilisateur d'un objet connecté d'accéder aux données qu'il génère et de les partager.",s:"Banque numérique"},
{id:"nu2-227",t:"num",q:"Quelle loi de 1988 réprime l'accès ou le maintien frauduleux dans un système de traitement automatisé de données ?",o:["La loi Toubon","La loi Evin","La loi Sapin","La loi Godfrain"],a:3,e:"Ces infractions figurent aux articles 323-1 et suivants du code pénal.",u:["https://fr.wikipedia.org/wiki/Loi_Godfrain"],s:"Banque numérique"},
{id:"nu2-228",t:"num",q:"Dans le cadre du DSA, que sont les « signaleurs de confiance » ?",o:["Des entités reconnues pour leur expertise, dont les signalements de contenus illicites sont traités en priorité par les plateformes","Des agents secrets","Des influenceurs rémunérés","Des robots de modération"],a:0,e:"En France, ils sont désignés par l'Arcom.",u:["https://fr.wikipedia.org/wiki/Règlement_sur_les_services_numériques"],s:"Banque numérique"},
{id:"nu2-229",t:"num",q:"Quel est le montant maximal de l'amende prévue par le DMA en cas de manquement d'un contrôleur d'accès (hors récidive) ?",o:["4 % du chiffre d'affaires annuel mondial","6 % du chiffre d'affaires annuel mondial","10 % du chiffre d'affaires annuel mondial","1 % du chiffre d'affaires annuel mondial"],a:2,e:"Jusqu'à 20 % en cas de récidive ; le DSA prévoit jusqu'à 6 %, le RGPD 4 %.",u:["https://fr.wikipedia.org/wiki/Règlement_sur_les_marchés_numériques"],s:"Banque numérique"}
);
